const CF_STORAGE_KEY='cf_tjce_fcc_guided_v23';
const CF_LEGACY_STORAGE_KEY='cf_tjce_fcc_guided_v22';
const CF_LETTERS=['A','B','C','D','E'];
let cfSession=null;

function cfFresh(){return {answers:{},weeks:{},lastWeek:'w1'}}
function cfState(){
 try{
   const raw=localStorage.getItem(CF_STORAGE_KEY)||localStorage.getItem(CF_LEGACY_STORAGE_KEY)||'{}';
   return {...cfFresh(),...JSON.parse(raw)};
 }catch(e){return cfFresh()}
}
function cfSave(st){localStorage.setItem(CF_STORAGE_KEY,JSON.stringify(st))}
function cfWeekState(id){
 const st=cfState(),x=st.weeks?.[id]||{};
 ['diagnostic','reading','theory','intermediate','deep','fixation'].forEach(k=>{if(typeof x[k]!=='boolean')x[k]=false});
 return x;
}
function cfUpdateWeek(id,patch){
 const st=cfState();st.weeks=st.weeks||{};st.weeks[id]={...(st.weeks[id]||{}),...patch};st.lastWeek=id;cfSave(st);renderAll();
}
function cfWeekPct(w){
 const st=cfWeekState(w.id),keys=['diagnostic','reading','theory','intermediate','deep','fixation'];
 return Math.round(keys.filter(k=>st[k]).length/keys.length*100);
}
function cfPool(w){return CF_QUESTIONS.filter(q=>w.topics.includes(q.t))}
function cfStats(){
 const st=cfState();let answered=0,correct=0,wrongIds=[];
 CF_QUESTIONS.forEach(q=>{
   const a=st.answers?.[q.id];
   if(a?.attempts){answered++;if(a.lastCorrect)correct++;if(a.everWrong&&!a.lastCorrect)wrongIds.push(q.id)}
 });
 return {answered,correct,wrongIds,accuracy:answered?Math.round(correct/answered*1000)/10:0};
}
function cfModuleErrors(w){const ids=new Set(cfStats().wrongIds);return cfPool(w).filter(q=>ids.has(q.id))}
function cfModuleOpenKey(id){return `central-v6:cf-open:${id}`}
function toggleCfModule(id){
 const el=document.querySelector(`.cf-module[data-cf="${id}"]`);if(!el)return;
 const open=!el.classList.contains('open');el.classList.toggle('open',open);localStorage.setItem(cfModuleOpenKey(id),open?'1':'0');
 if(open){const w=CF_WEEKS.find(x=>x.id===id);if(w)saveLast({cfWeek:id,title:`Constitucional • Módulo ${w.num} • ${w.title}`,at:Date.now()})}
}
function openCfLast(id){
 openHome();localStorage.setItem('central-v6:open:cf','1');localStorage.setItem(cfModuleOpenKey(id),'1');
 setTimeout(()=>{renderSubjects();document.querySelector(`.cf-module[data-cf="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})},40);
}
function cfDeterministic(list,count,seed){
 if(!list.length)return[];
 const st=cfState(),unseen=list.filter(q=>!st.answers?.[q.id]?.attempts),seen=list.filter(q=>st.answers?.[q.id]?.attempts),src=[...unseen,...seen];
 let h=2166136261;for(const c of String(seed))h=(Math.imul(h^c.charCodeAt(0),16777619))>>>0;
 return src.map((q,i)=>({q,k:(h^(Math.imul(i+1,2654435761)))>>>0})).sort((a,b)=>a.k-b.k).slice(0,Math.min(count,src.length)).map(x=>x.q);
}
function cfOptionOrder(q,mode){
 const st=cfState(),a=[0,1,2,3,4];let h=2166136261;
 const seed=q.id+':'+(st.answers?.[q.id]?.attempts||0)+':'+mode;
 for(const c of seed)h=(Math.imul(h^c.charCodeAt(0),16777619))>>>0;
 for(let i=a.length-1;i>0;i--){h=(Math.imul(h^(h>>>13),1597334677))>>>0;const j=h%(i+1);[a[i],a[j]]=[a[j],a[i]]}
 return a;
}
function cfSourceKind(q){return q.real===false?'Inédita • estilo FCC':'FCC real'}
function cfLegalUpdate(q){
 const raw=((q.r||'')+' '+(q.source||'')),ys=raw.match(/\b20\d{2}\b/g),y=ys?Math.max(...ys.map(Number)):null;
 if(!y||q.real===false)return '';
 const x=((q.q||'')+' '+(q.o||[]).join(' ')).toLowerCase();
 if(q.t==='nacionalidade'&&y<2024&&/(perd\w*.{0,80}nacionalidade|cancelad\w*.{0,80}naturaliza|outra nacionalidade|atividade nociva)/s.test(x))return 'Questão anterior à EC 131/2023. Confira a redação constitucional atual sobre perda da nacionalidade.';
 if(q.t==='organizacao'&&y<2026&&/munic/.test(x)&&/(cria|incorpora|fus|desmembr)/.test(x))return 'Questão anterior à LC 230/2026. Confira a disciplina atual do art. 18, §4º.';
 if(q.t==='administracao'&&y<2026&&/acumul/.test(x)&&/professor/.test(x))return 'Questão anterior à EC 138/2025. Confira a redação atual do art. 37, XVI, b.';
 if(q.t==='administracao'&&y<2025&&/regime jur[ií]dico [uú]nico|regime [uú]nico/.test(x))return 'Questão anterior ao julgamento final da ADI 2.135. Confira o entendimento atual estudado no módulo.';
 if(q.t==='judiciario'&&y<2026&&/precat[oó]r/.test(x))return 'Questão anterior à EC 136/2025. Confira a redação atual do art. 100.';
 if(q.t==='sociais'&&y<2024&&/contribui[cç][aã]o assistencial|n[aã]o sindicaliz/.test(x))return 'Questão anterior à consolidação do Tema 935/STF.';
 if(q.t==='defensoria'&&y<2024&&/honor[aá]rios/.test(x))return 'Questão anterior ao Tema 1002/STF sobre honorários da Defensoria Pública.';
 return '';
}
const CF_ANKI={"w1":"02 DIREITO CONSTITUCIONAL::01 CONSTITUIÇÃO, NORMAS E PRINCÍPIOS FUNDAMENTAIS","w2":"02 DIREITO CONSTITUCIONAL::02 DIREITOS E DEVERES INDIVIDUAIS E COLETIVOS","w3":"02 DIREITO CONSTITUCIONAL::03 DIREITOS SOCIAIS, NACIONALIDADE E DIREITOS POLÍTICOS","w4":"02 DIREITO CONSTITUCIONAL::04 ORGANIZAÇÃO DO ESTADO","w5":"02 DIREITO CONSTITUCIONAL::05 ADMINISTRAÇÃO PÚBLICA E SERVIDORES","w6":"02 DIREITO CONSTITUCIONAL::06 PODER LEGISLATIVO - ORGANIZAÇÃO E ATRIBUIÇÕES","w7":"02 DIREITO CONSTITUCIONAL::07 PROCESSO LEGISLATIVO E FISCALIZAÇÃO","w8":"02 DIREITO CONSTITUCIONAL::08 PODER EXECUTIVO","w9":"02 DIREITO CONSTITUCIONAL::09 PODER JUDICIÁRIO - DISPOSIÇÕES GERAIS E STF","w10":"02 DIREITO CONSTITUCIONAL::10 CNJ, STJ, JUSTIÇA DO TRABALHO E CSJT","w11":"02 DIREITO CONSTITUCIONAL::11 FUNÇÕES ESSENCIAIS À JUSTIÇA","w12":"02 DIREITO CONSTITUCIONAL::12 CONTROLE DE CONSTITUCIONALIDADE"};
function cfResKey(id){return `central-v6:cf-res:${id}`}
function cfResources(id){try{return JSON.parse(localStorage.getItem(cfResKey(id))||'{}')}catch(e){return {}}}
function editCfResource(id,kind){
 const r=cfResources(id),v=prompt(`Cole o link de ${kind==='tec'?'TEC Concursos':'QConcursos'}:`,r[kind]||'https://');
 if(v===null)return;const value=v.trim();if(!value){r[kind]='';localStorage.setItem(cfResKey(id),JSON.stringify(r));renderSubjects();return}
 const u=safeUrl(value);if(!u){alert('Link inválido.');return}r[kind]=u;localStorage.setItem(cfResKey(id),JSON.stringify(r));renderSubjects();
}
function openCfResource(id,kind){const r=cfResources(id),u=safeUrl(r[kind]);if(u)openExternalUrl(u);else editCfResource(id,kind)}
function cfNoteKey(id){return `central-v6:cf-note:${id}`}
function saveCfNote(id){const el=document.getElementById(`cf-note-${id}`);if(!el)return;localStorage.setItem(cfNoteKey(id),el.value);alert('Anotação salva.')}
function cfStep(n,title,desc,done,body){
 return `<section class="cf-step ${done?'done':''}"><div class="cf-step-head"><div class="cf-step-no">${done?'✓':n}</div><div class="cf-step-copy"><b>${title}</b><small>${desc}</small></div></div><div class="cf-step-body">${body}</div></section>`;
}
function renderConstitutionalMaster(){
 const st=cfStats(),real=CF_QUESTIONS.filter(q=>q.real!==false).length,ined=CF_QUESTIONS.length-real;
 return `<div class="cf-master-tools">
   <button onclick="renderCfErrorPanel()">⚠ Erros ${st.wrongIds.length?`(${st.wrongIds.length})`:''}</button>
   <button onclick="exportCfProgress()">💾 Backup</button>
   <button onclick="document.getElementById('cf-import-file').click()">↥ Restaurar</button>
   <input class="cf-file" id="cf-import-file" type="file" accept=".json,application/json" onchange="importCfProgress(this)">
 </div>
 <div class="cf-metrics">
   <div class="cf-metric"><small>Banco do curso</small><b>${CF_QUESTIONS.length}</b></div>
   <div class="cf-metric"><small>Respondidas</small><b>${st.answered}</b></div>
   <div class="cf-metric"><small>Aproveitamento</small><b>${st.answered?st.accuracy+'%':'—'}</b></div>
   <div class="cf-metric"><small>Erros pendentes</small><b>${st.wrongIds.length}</b></div>
 </div>
 <div id="cf-session-host"></div>
 <div id="cf-errors-host"></div>
 <div class="cf-modules">${CF_WEEKS.map(renderCfModule).join('')}</div>`;
}
function renderCfModule(w){
 const ws=cfWeekState(w.id),pct=cfWeekPct(w),pool=cfPool(w),real=pool.filter(q=>q.real!==false),ined=pool.filter(q=>q.real===false),errors=cfModuleErrors(w);
 const open=localStorage.getItem(cfModuleOpenKey(w.id))==='1';
 const diag=Math.min(5,real.length),inter=Math.min(8,real.length),finalN=Math.min(15,real.length),extra=Math.min(30,real.length),r=cfResources(w.id),tecAuto=(typeof window.tecContextButtons==='function'?window.tecContextButtons(w.id,'cf-btn'):'');
 return `<section class="cf-module ${open?'open':''}" data-cf="${w.id}">
   <button class="cf-module-head" onclick="toggleCfModule('${w.id}')">
     <span class="cf-module-no">MÓDULO ${w.num}</span><span class="cf-module-title">${esc(w.title)}</span>
     <span class="cf-module-stat">${pct}% • ${real.length} FCC + ${ined.length} inéditas</span><span class="chev">⌄</span>
   </button>
   <div class="cf-module-body">
     <div class="cf-module-bar"><span style="width:${pct}%"></span></div>
     <div class="cf-subtitle">${esc(w.subtitle)}</div>
     <details class="cf-syllabus"><summary>Matriz do edital • ${w.outline.length} pontos</summary><div class="cf-micro-grid">${w.outline.map(x=>`<span class="cf-micro">${esc(x)}</span>`).join('')}</div></details>
     <div class="cf-steps">
       ${cfStep(1,'Diagnóstico','Questões FCC antes da teoria.',ws.diagnostic,real.length?`<button class="cf-btn primary" onclick="startCfQuiz('${w.id}','diagnostic',${diag})">${ws.diagnostic?'Refazer diagnóstico':'Começar '+diag+' FCC'}</button>`:`<span class="muted small">Sem questões reais suficientes.</span>`)}
       ${cfStep(2,'Leitura orientada','Dispositivos e pontos para observar na Constituição.',ws.reading,`<div class="cf-reading"><strong>${esc(w.read)}</strong><ul>${w.read_focus.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="cf-actions"><button class="cf-btn primary" onclick="openLeiSecaEnxuta(null,'cf','cf-m${String(w.num).padStart(2,'0')}')">📖 Decorando deste módulo</button><button class="cf-btn" onclick="openVadeMecum(null,'cf')">Abrir Vade Mecum</button><button class="cf-btn ${ws.reading?'good':''}" onclick="cfUpdateWeek('${w.id}',{reading:${!ws.reading}})">${ws.reading?'✓ Concluída':'Marcar concluída'}</button></div>`)}
       ${cfStep(3,'Teoria nuclear','Base completa antes da segunda bateria.',ws.theory,`<div class="cf-theory-grid">${w.theory.map((t,i)=>`<details class="cf-theory" ${i===0?'open':''}><summary>${esc(t[0])}</summary><div class="cf-theory-text">${esc(t[1])}</div></details>`).join('')}</div><div class="cf-actions"><button class="cf-btn ${ws.theory?'good':''}" onclick="cfUpdateWeek('${w.id}',{theory:${!ws.theory}})">${ws.theory?'✓ Teoria concluída':'Marcar teoria concluída'}</button></div>`)}
       ${cfStep(4,'Questões intermediárias','Bateria curta depois da teoria.',ws.intermediate,real.length?`<button class="cf-btn primary" onclick="startCfQuiz('${w.id}','intermediate',${inter})">${ws.intermediate?'Refazer '+inter+' FCC':'Fazer '+inter+' FCC'}</button>`:`<span class="muted small">Sem fila real suficiente.</span>`)}
       ${cfStep(5,'Aprofundamento FCC','Distinções, exceções e pegadinhas de nível mais alto.',ws.deep,`<div class="cf-advanced-grid">${w.advanced.map(t=>`<div class="cf-advanced"><b>${esc(t[0])}</b><div>${esc(t[1])}</div></div>`).join('')}</div><div class="cf-actions"><button class="cf-btn ${ws.deep?'good':''}" onclick="cfUpdateWeek('${w.id}',{deep:${!ws.deep}})">${ws.deep?'✓ Aprofundamento concluído':'Marcar aprofundamento concluído'}</button></div>`)}
       ${cfStep(6,'Bateria final FCC','Misture literalidade, exceções e casos concretos.',ws.fixation,`<div class="cf-actions">${real.length?`<button class="cf-btn primary" onclick="startCfQuiz('${w.id}','fixation',${finalN})">FCC real • ${finalN}</button>${extra>finalN?`<button class="cf-btn" onclick="startCfQuiz('${w.id}','extra',${extra})">FCC extra • ${extra}</button>`:''}`:''}${ined.length?`<button class="cf-btn" onclick="startCfQuiz('${w.id}','coverage',${Math.min(15,ined.length)})">Cobertura inédita • ${Math.min(15,ined.length)}</button>`:''}</div><div class="cf-coverage">${real.length} questões FCC reais + ${ined.length} inéditas neste módulo.</div>`)}
       ${cfStep(7,'Revisão de erros',errors.length?`${errors.length} erro(s) pendente(s) neste módulo.`:'Nenhum erro pendente.',errors.length===0,errors.length?`<button class="cf-btn bad" onclick="startCfQuiz('${w.id}','errors',999)">Refazer ${errors.length} erro(s)</button>`:`<span class="muted small">A fila fica vazia quando a questão é acertada novamente.</span>`)}
     </div>
     <details class="cf-resources"><summary class="muted small" style="cursor:pointer">Recursos do módulo • TEC/QC, Anki e anotações</summary>
       <div class="cf-resource-grid" style="margin-top:8px">
         <div class="cf-resource-box"><h4>Questões externas</h4><div class="cf-actions">${tecAuto}${r.tec?`<button class="cf-btn" onclick="openCfResource('${w.id}','tec')">TEC personalizado ↗</button>`:(tecAuto?'':`<button class="cf-btn" onclick="openCfResource('${w.id}','tec')">+ TEC</button>`)}<button class="cf-btn" onclick="openCfResource('${w.id}','qc')">${r.qc?'Abrir QC':'+ QC'}</button></div></div>
         <div class="cf-resource-box"><h4>Decorando a Lei</h4><button class="cf-btn" onclick="openLeiSecaEnxuta(null,'cf','cf-m${String(w.num).padStart(2,'0')}')">Abrir artigos deste módulo</button></div>
         <div class="cf-resource-box"><h4>Anki</h4>${CF_ANKI[w.id]?`<button class="cf-btn" onclick="openAnkiDeck('${escJs(CF_ANKI[w.id])}','${escJs(w.title)}')">Abrir baralho</button>`:'<span class="muted small">Sem subbaralho específico mapeado.</span>'}</div>
         <div class="cf-resource-box" style="grid-column:1/-1"><h4>Anotação</h4><textarea class="cf-notes" id="cf-note-${w.id}" placeholder="Regra, artigo, pegadinha ou dúvida...">${esc(localStorage.getItem(cfNoteKey(w.id))||'')}</textarea><div class="cf-actions"><button class="cf-btn" onclick="saveCfNote('${w.id}')">Salvar anotação</button></div></div>
       </div>
     </details>
   </div>
 </section>`;
}
function startCfQuiz(id,mode,count){
 const w=CF_WEEKS.find(x=>x.id===id);if(!w)return;
 let list=cfPool(w),st=cfState();
 if(mode==='errors')list=list.filter(q=>st.answers?.[q.id]?.everWrong&&!st.answers?.[q.id]?.lastCorrect);
 else if(mode==='coverage')list=list.filter(q=>q.real===false);
 else {const real=list.filter(q=>q.real!==false);if(real.length)list=real}
 if(!list.length){alert('Não há questões nessa fila.');return}
 list=cfDeterministic(list,Math.min(count,list.length),id+mode+Object.keys(st.answers||{}).length);
 cfSession={week:w,mode,list,index:0,score:0,errors:[],answered:false,order:null};
 localStorage.setItem('central-v6:open:cf','1');localStorage.setItem(cfModuleOpenKey(id),'1');
 renderCfQuestion();
}
function cfModeName(mode){return ({diagnostic:'Diagnóstico',intermediate:'Questões intermediárias',fixation:'Bateria final FCC',extra:'Bateria extra',coverage:'Cobertura inédita',errors:'Revisão de erros'})[mode]||'Questões'}
function renderCfQuestion(){
 if(!cfSession)return;const host=document.getElementById('cf-session-host');if(!host)return;
 const q=cfSession.list[cfSession.index];cfSession.answered=false;cfSession.order=cfOptionOrder(q,cfSession.mode);
 const legal=cfLegalUpdate(q);
 host.innerHTML=`<section class="cf-session">
   <div class="cf-session-head"><div><b>${cfModeName(cfSession.mode)} • Módulo ${cfSession.week.num}</b><br><span class="muted small">${esc(cfSession.week.title)}</span></div><button class="pt-inline-close" onclick="closeCfSession()">✕ fechar</button></div>
   <div class="cf-session-body">
     <div class="cf-qtop"><span>${cfSession.index+1}/${cfSession.list.length}</span><span>${cfSourceKind(q)}</span></div>
     <div class="cf-qbar"><span style="width:${((cfSession.index)/cfSession.list.length)*100}%"></span></div>
     <article class="cf-question">
       <div class="cf-qmeta"><span class="cf-chip">${cfSourceKind(q)}</span><span class="cf-chip">${esc(q.subject||cfSession.week.title)}</span>${legal?'<span class="cf-chip">⚠ atualização</span>':''}</div>
       <h3>${esc(q.q)}</h3>
       <div class="cf-options">${cfSession.order.map((orig,display)=>`<div class="cf-option-row"><button class="cf-option" data-cf-opt="${orig}" onclick="answerCfQuestion(${orig})"><span class="cf-letter">${CF_LETTERS[display]}</span><span>${esc(q.o[orig])}</span></button><button class="cf-strike" data-cf-strike="${orig}" onclick="toggleCfStrike(${orig})">S̶</button></div>`).join('')}</div>
       <div id="cf-feedback"></div><div class="cf-actions" style="justify-content:flex-end"><button id="cf-next" class="cf-btn primary hidden" onclick="nextCfQuestion()">${cfSession.index+1===cfSession.list.length?'Ver resultado':'Próxima questão'}</button></div>
     </article>
   </div>
 </section>`;
 host.scrollIntoView({behavior:'smooth',block:'start'});
}
function toggleCfStrike(i){
 if(!cfSession||cfSession.answered)return;
 document.querySelector(`[data-cf-opt="${i}"]`)?.classList.toggle('struck');
 document.querySelector(`[data-cf-strike="${i}"]`)?.classList.toggle('active');
}
function answerCfQuestion(i){
 if(!cfSession||cfSession.answered)return;cfSession.answered=true;
 const q=cfSession.list[cfSession.index],ok=i===q.a,st=cfState(),prev=st.answers?.[q.id]||{attempts:0,everWrong:false,lastCorrect:false};
 prev.attempts++;prev.lastCorrect=ok;prev.everWrong=prev.everWrong||!ok;prev.lastAt=Date.now();st.answers=st.answers||{};st.answers[q.id]=prev;cfSave(st);
 if(ok)cfSession.score++;else cfSession.errors.push(q.id);
 document.querySelectorAll('[data-cf-opt]').forEach(b=>{const orig=Number(b.dataset.cfOpt);b.disabled=true;if(orig===q.a)b.classList.add('correct');if(orig===i&&!ok)b.classList.add('wrong')});
 document.querySelectorAll('[data-cf-strike]').forEach(b=>b.disabled=true);
 const correctDisplay=cfSession.order.indexOf(q.a),legal=cfLegalUpdate(q),fb=document.getElementById('cf-feedback');
 const perAlt=Array.isArray(q.oe)?`<details style="margin-top:8px"><summary style="cursor:pointer;font-weight:800">Análise das alternativas</summary><div style="margin-top:6px">${cfSession.order.map((orig,disp)=>`<div style="border-top:1px solid rgba(255,255,255,.08);padding:6px 0"><b>${CF_LETTERS[disp]} • ${orig===q.a?'CORRETA':'ERRADA'}</b><br>${esc(q.oe[orig]||'')}</div>`).join('')}</div></details>`:'';
 fb.className=`cf-feedback ${ok?'good':'bad'}`;fb.innerHTML=`<b>${ok?'Correto.':'Incorreto. Gabarito: '+CF_LETTERS[correctDisplay]}</b><div style="margin-top:5px">${esc(q.e||'Revise o ponto correspondente no módulo.')}</div>${legal?`<div class="cf-update"><b>Atualização jurídica:</b> ${esc(legal)}</div>`:''}${perAlt}<div class="cf-source">${esc(q.r||q.source||'Banco FCC')}</div>`;
 document.getElementById('cf-next').classList.remove('hidden');renderSummary();
}
function nextCfQuestion(){
 if(!cfSession||!cfSession.answered)return;
 if(cfSession.index+1<cfSession.list.length){cfSession.index++;renderCfQuestion()}else finishCfQuiz();
}
function finishCfQuiz(){
 const sess=cfSession,w=sess.week,st=cfState();st.weeks=st.weeks||{};const ws=st.weeks[w.id]||{};
 if(sess.mode==='diagnostic')ws.diagnostic=true;if(sess.mode==='intermediate')ws.intermediate=true;if(sess.mode==='fixation')ws.fixation=true;
 st.weeks[w.id]=ws;st.lastWeek=w.id;cfSave(st);
 const total=sess.list.length,pct=Math.round(sess.score/total*100),host=document.getElementById('cf-session-host');
 host.innerHTML=`<section class="cf-session"><div class="cf-session-head"><b>${cfModeName(sess.mode)} concluído</b><button class="pt-inline-close" onclick="closeCfSession()">✕</button></div><div class="cf-session-body cf-result"><div class="cf-score">${pct}%</div><div class="cf-result-grid"><div><b>${sess.score}</b><small>acertos</small></div><div><b>${total-sess.score}</b><small>erros</small></div><div><b>${cfWeekPct(w)}%</b><small>módulo</small></div></div><div class="cf-actions" style="justify-content:center"><button class="cf-btn primary" onclick="closeCfSession();openCfLast('${w.id}')">Voltar ao módulo</button>${sess.errors.length?`<button class="cf-btn bad" onclick="startCfQuiz('${w.id}','errors',999)">Refazer erros</button>`:''}</div></div></section>`;
 renderAll();localStorage.setItem('central-v6:open:cf','1');localStorage.setItem(cfModuleOpenKey(w.id),'1');
 setTimeout(()=>{const h=document.getElementById('cf-session-host');if(h)h.innerHTML=host.innerHTML},0);
}
function closeCfSession(){cfSession=null;const h=document.getElementById('cf-session-host');if(h)h.innerHTML=''}
function renderCfErrorPanel(){
 const host=document.getElementById('cf-errors-host');if(!host)return;
 const ids=new Set(cfStats().wrongIds),list=CF_QUESTIONS.filter(q=>ids.has(q.id));
 if(!list.length){host.innerHTML='<div class="cf-error-panel"><b>Nenhum erro pendente.</b></div>';return}
 const weak={};list.forEach(q=>{const k=q.subject||'Assunto';weak[k]=(weak[k]||0)+1});
 const top=Object.entries(weak).sort((a,b)=>b[1]-a[1]).slice(0,6);
 host.innerHTML=`<div class="cf-error-panel"><div style="display:flex;justify-content:space-between;gap:8px"><div><b>Caderno automático de erros</b><div class="muted small">${list.length} questão(ões) pendente(s)</div></div><button class="pt-inline-close" onclick="document.getElementById('cf-errors-host').innerHTML=''">✕</button></div><div class="cf-micro-grid">${top.map(([x,n])=>`<span class="cf-micro">${esc(x)} • ${n}</span>`).join('')}</div><div class="cf-actions"><button class="cf-btn bad" onclick="startCfGlobalErrors()">Refazer todos</button></div>${CF_WEEKS.map(w=>{const n=cfModuleErrors(w).length;return n?`<div class="cf-error-row"><b>Módulo ${w.num} • ${esc(w.title)}</b><small>${n} erro(s)</small><div class="cf-actions"><button class="cf-btn" onclick="startCfQuiz('${w.id}','errors',999)">Revisar módulo</button></div></div>`:''}).join('')}</div>`;
 host.scrollIntoView({behavior:'smooth',block:'start'});
}
function startCfGlobalErrors(){
 const st=cfState(),list=CF_QUESTIONS.filter(q=>st.answers?.[q.id]?.everWrong&&!st.answers?.[q.id]?.lastCorrect);if(!list.length)return;
 cfSession={week:CF_WEEKS[0],mode:'errors',list:cfDeterministic(list,list.length,'global-errors'),index:0,score:0,errors:[],answered:false,order:null};renderCfQuestion();
}
function exportCfProgress(){
 const payload={app:'CF TJCE FCC',version:'2.15-central',exportedAt:new Date().toISOString(),storageKey:CF_STORAGE_KEY,state:cfState()};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=`backup-constitucional-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);
}
async function importCfProgress(input){
 const file=input.files?.[0];if(!file)return;
 try{const obj=JSON.parse(await file.text()),st=obj.state||obj;if(!st.answers||!st.weeks)throw new Error();if(!confirm('Restaurar este progresso de Constitucional?'))return;cfSave({...cfFresh(),...st});renderAll();alert('Progresso restaurado.')}catch(e){alert('Backup inválido.')}input.value='';
}

const PENAL_WEEKS=[{"id":"p1","num":1,"title":"Princípios, interpretação, analogia e conflito aparente","subtitle":"Princípios penais; interpretação; analogia; conflito aparente","topics":["pen-m01"],"read":"CF, art. 5º, XXXIX a XLVII; CP, arts. 1º e 12.","read_focus":["Separe legalidade, anterioridade e reserva legal.","Diferencie interpretação extensiva de analogia.","A analogia não pode criar crime, agravar pena ou piorar a situação do acusado.","No conflito aparente, reconheça especialidade, subsidiariedade, consunção e alternatividade."],"outline":["legalidade","anterioridade","reserva legal","taxatividade","irretroatividade gravosa","humanidade","intranscendência","individualização","intervenção mínima","fragmentariedade","ofensividade","insignificância","interpretação extensiva","interpretação analógica","analogia in bonam partem","especialidade","subsidiariedade","consunção","alternatividade"],"theory":[["Legalidade em sentido amplo","Não há crime sem lei anterior que o defina nem pena sem prévia cominação legal. A regra exige lei formal, anterior, escrita, estrita e certa para incriminar."],["Princípios limitadores","Intervenção mínima, fragmentariedade, subsidiariedade, ofensividade, proporcionalidade, culpabilidade e humanidade funcionam como limites materiais ao poder punitivo."],["Interpretação e analogia","Interpretação revela o sentido de texto existente; analogia integra lacuna por semelhança. Em matéria penal, a analogia prejudicial é vedada; a favorável pode ser admitida quando houver lacuna verdadeira."],["Conflito aparente de normas","Uma única conduta parece alcançada por mais de uma norma, mas apenas uma prevalece. Especialidade, subsidiariedade, consunção e alternatividade evitam dupla valoração."],["Insignificância","Exclui a tipicidade material quando a lesão é irrelevante segundo os vetores jurisprudenciais. Não decorre automaticamente do pequeno valor e depende do contexto concreto."]],"advanced":[["Analogia x interpretação","A FCC costuma chamar de analogia uma ampliação que ainda cabe no texto; primeiro verifique se existe lacuna."],["Consunção","O fato-meio normalmente absorvido deve ser etapa normal, necessária ou usual do fato-fim, sem autonomia lesiva relevante."],["Lex tertia","A combinação judicial de trechos de leis sucessivas para criar uma terceira disciplina encontra resistência na jurisprudência."]],"editalModule":"pen-m01","ankiDeck":"05 DIREITO PENAL::01 PRINCÍPIOS, INTERPRETAÇÃO, ANALOGIA E CONFLITO APARENTE","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p2","num":2,"title":"Aplicação da lei penal no tempo e no espaço","subtitle":"CP, arts. 1º a 12","topics":["pen-m02"],"read":"CP, arts. 1º a 12; CF, art. 5º, XXXIX e XL.","read_focus":["Art. 2º: abolitio criminis e retroatividade da lei mais benéfica.","Art. 3º: ultratividade da lei excepcional ou temporária.","Art. 4º: teoria da atividade para o tempo do crime.","Art. 6º: teoria da ubiquidade para o lugar.","Art. 7º: separe extraterritorialidade incondicionada, condicionada e hipercondicionada."],"outline":["lei penal no tempo","abolitio criminis","novatio legis in mellius","novatio legis in pejus","lei intermediária","lei temporária","lei excepcional","tempo do crime","territorialidade temperada","território por extensão","lugar do crime","extraterritorialidade","pena cumprida no estrangeiro","sentença estrangeira","contagem de prazo penal","frações não computáveis","lei especial"],"theory":[["Sucessão de leis","A lei posterior mais favorável retroage, ainda que exista condenação transitada em julgado. A lei posterior mais severa não alcança fato anterior."],["Abolitio criminis","Quando a lei deixa de considerar o fato crime, cessam a execução e os efeitos penais da condenação; os efeitos civis não desaparecem automaticamente."],["Tempo e lugar","O CP adota a atividade para o tempo: ação ou omissão. Para o lugar, adota a ubiquidade: local da conduta e local do resultado efetivo ou pretendido."],["Territorialidade","A lei brasileira aplica-se ao território nacional, sem prejuízo de tratados e regras internacionais. Aeronaves e embarcações recebem disciplina própria no art. 5º."],["Extraterritorialidade e efeitos externos","O art. 7º organiza hipóteses e condições; os arts. 8º e 9º tratam da pena cumprida fora e da homologação de sentença estrangeira."]],"advanced":[["Lei temporária","Aplica-se ao fato praticado durante sua vigência mesmo depois de encerrado o prazo: autorrevogabilidade e ultratividade."],["Crime continuado e permanente","A sucessão de lei mais grave enquanto persiste a permanência ou continuidade exige atenção à Súmula 711 do STF."],["Prazo penal","Inclui-se o dia do começo; não confunda com a contagem processual."]],"editalModule":"pen-m02","ankiDeck":"05 DIREITO PENAL::02 APLICAÇÃO DA LEI PENAL NO TEMPO E NO ESPAÇO","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p3","num":3,"title":"Ilicitude","subtitle":"CP, arts. 23 a 25","topics":["pen-m03"],"read":"CP, arts. 23 a 25; STF, ADPF 779.","read_focus":["Memorize as quatro causas do art. 23.","Excesso doloso ou culposo é punível.","Estado de necessidade exige perigo atual e inevitável.","Legítima defesa exige agressão injusta, atual ou iminente, e uso moderado dos meios necessários."],"outline":["ilicitude formal e material","causas legais","estado de necessidade","perigo atual","dever de enfrentar","legítima defesa","agressão injusta","meios necessários","moderação","estrito cumprimento do dever","exercício regular de direito","excesso punível","causas supralegais"],"theory":[["Estrutura","A prática de fato típico indica ilicitude, salvo incidência de causa de justificação."],["Art. 23","Excluem a ilicitude: estado de necessidade, legítima defesa, estrito cumprimento de dever legal e exercício regular de direito."],["Estado de necessidade","Protege direito próprio ou alheio contra perigo atual não provocado voluntariamente e inevitável, quando não era razoável exigir o sacrifício."],["Legítima defesa","Repele agressão humana injusta, atual ou iminente, a direito próprio ou de terceiro, com meios necessários usados moderadamente."],["Excesso","Cessados os pressupostos da justificante, a continuação ou desproporção pode gerar responsabilidade dolosa ou culposa."]],"advanced":[["Honra e violência","A tese de legítima defesa da honra é inconstitucional segundo a ADPF 779."],["Ofendículos","A classificação pode variar entre exercício regular e legítima defesa preordenada; o essencial é necessidade e moderação."],["Erro sobre justificante","A descriminante putativa liga a análise da ilicitude ao regime de erro e culpabilidade."]],"editalModule":"pen-m03","ankiDeck":"05 DIREITO PENAL::03 ILICITUDE","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p4","num":4,"title":"Culpabilidade","subtitle":"CP, arts. 20, §1º, e 21, 22 e 26 a 28","topics":["pen-m04"],"read":"CP, arts. 20, §1º, 21, 22 e 26 a 28.","read_focus":["Estruture: imputabilidade, potencial consciência da ilicitude e exigibilidade.","Erro de proibição inevitável isenta; evitável reduz.","Coação moral irresistível e ordem não manifestamente ilegal afastam a exigibilidade.","Embriaguez voluntária ou culposa não exclui imputabilidade."],"outline":["conceito normativo","imputabilidade","doença mental","semi-imputabilidade","menoridade","emoção e paixão","embriaguez","potencial consciência","erro de proibição","exigibilidade","coação irresistível","obediência hierárquica","descriminante putativa"],"theory":[["Conceito","Culpabilidade é o juízo de reprovação pessoal do fato, apoiado em imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa."],["Imputabilidade","O art. 26 adota critério biopsicológico: causa mental e incapacidade inteira no momento da conduta. O parágrafo único disciplina a redução por capacidade não inteira."],["Erro de proibição","Incide sobre a ilicitude: se inevitável, isenta de pena; se evitável, permite redução de um sexto a um terço."],["Inexigibilidade","Na coação irresistível e na estrita obediência a ordem não manifestamente ilegal, pune-se o autor da coação ou da ordem."],["Embriaguez","A voluntária ou culposa não exclui imputabilidade; a completa, por caso fortuito ou força maior, pode isentar quando elimina inteiramente a capacidade."]],"advanced":[["Coação física","A coação física irresistível elimina a própria conduta; a moral irresistível atua na culpabilidade."],["Ordem superior","Se a ilegalidade é manifesta, o subordinado não se beneficia da excludente."],["Actio libera in causa","A incapacidade provocada pode não afastar responsabilidade quando o agente era livre e imputável no momento antecedente relevante."]],"editalModule":"pen-m04","ankiDeck":"05 DIREITO PENAL::04 CULPABILIDADE","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p5","num":5,"title":"Concurso de pessoas","subtitle":"CP, arts. 29 a 31","topics":["pen-m05"],"read":"CP, arts. 29 a 31.","read_focus":["Regra monista do art. 29.","Participação de menor importância reduz a pena.","Cooperação dolosamente distinta.","Circunstâncias pessoais não se comunicam, salvo quando elementares."],"outline":["autoria","coautoria","participação","teoria monista","liame subjetivo","relevância causal","identidade de infração","menor importância","cooperação dolosamente distinta","comunicabilidade","ajuste impunível"],"theory":[["Regra unitária","Quem concorre para o crime incide nas penas a ele cominadas, na medida de sua culpabilidade."],["Requisitos","Pluralidade de agentes e condutas, relevância causal, liame subjetivo e identidade de infração formam o núcleo do concurso."],["Participação","Induzimento, instigação ou auxílio dependem de fato principal ao menos típico e ilícito na concepção limitada da acessoriedade."],["Art. 30","Condições e circunstâncias pessoais não se comunicam; comunicam-se quando integram o tipo como elementares."],["Art. 31","Ajuste, determinação, instigação e auxílio não são puníveis se o crime não chega, ao menos, a ser tentado, salvo previsão autônoma."]],"advanced":[["Autoria mediata","O autor se vale de pessoa como instrumento; não se confunde com mero mandante."],["Participação de menor importância","A redução recai sobre participação de menor relevo, não sobre coautoria."],["Desvio subjetivo","Se o concorrente quis crime menos grave, aplica-se a pena deste, com aumento se o resultado mais grave era previsível."]],"editalModule":"pen-m05","ankiDeck":"05 DIREITO PENAL::05 CONCURSO DE PESSOAS","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p6","num":6,"title":"Penas: espécies e cominação","subtitle":"CP, arts. 32 a 58","topics":["pen-m06"],"read":"CP, arts. 32 a 58, com foco em espécies e cominação.","read_focus":["Art. 32: privativas, restritivas e multa.","Diferencie reclusão e detenção.","Memorize as restritivas do art. 43.","Leia as regras de cominação dos arts. 53 a 58 sem ampliar para dosimetria fora do edital."],"outline":["espécies de pena","reclusão","detenção","regimes","direitos do preso","trabalho do preso","restritivas de direitos","prestação pecuniária","perda de bens","serviços","interdições","limitação de fim de semana","multa","cominação"],"theory":[["Art. 32","As penas são privativas de liberdade, restritivas de direitos e multa."],["Privativas","Reclusão e detenção possuem regimes iniciais legalmente diferenciados; a prisão simples pertence às contravenções."],["Restritivas","São autônomas e substituem as privativas quando presentes os requisitos legais; as modalidades estão no art. 43."],["Multa","A pena de multa segue o sistema de dias-multa, com quantidade e valor unitário nos limites legais."],["Cominação","Os arts. 53 a 58 dizem como cada espécie aparece nos tipos e como se relaciona com a pena privativa cominada."]],"advanced":[["Escopo do edital","Aplicação concreta da pena, concurso de crimes, sursis e livramento foram arquivados porque o edital nomeia espécies e cominação."],["Restritiva x efeito","Perda de bens como pena não se confunde com efeito patrimonial da condenação."],["Multa","Não confunda quantidade de dias-multa com valor de cada dia-multa."]],"editalModule":"pen-m06","ankiDeck":"05 DIREITO PENAL::06 PENAS - ESPÉCIES E COMINAÇÃO","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p7","num":7,"title":"Ação penal, punibilidade, extinção e prescrição","subtitle":"CP, arts. 100 a 120","topics":["pen-m07"],"read":"CP, arts. 100 a 120; Lei 15.438/2026.","read_focus":["Ação pública incondicionada é a regra.","Decadência comum: seis meses; violência doméstica e familiar contra a mulher: doze meses.","Art. 107: causas de extinção.","Separe prescrição da pretensão punitiva e executória.","Leia termos iniciais, interrupção e suspensão."],"outline":["ação pública","representação","requisição","ação privada","subsidiária","decadência","renúncia","perdão","perempção","punibilidade","morte","anistia","graça","indulto","abolitio","retratação","perdão judicial","prescrição punitiva","prescrição executória","termos iniciais","interrupção","suspensão"],"theory":[["Ação penal","A regra é a ação pública, promovida pelo Ministério Público; condicionamento ou iniciativa privada dependem de previsão."],["Decadência","O art. 103 traz seis meses como regra. Desde a Lei 15.438/2026, o parágrafo único fixa doze meses para crimes no âmbito de violência doméstica e familiar contra a mulher."],["Extinção","O art. 107 enumera causas, sem impedir outras previstas na Parte Especial ou em leis. A extinção da punibilidade não apaga necessariamente todos os efeitos civis."],["Prescrição punitiva","Antes do trânsito final para a acusação, relaciona-se ao máximo da pena em abstrato ou, em momentos legais, à pena aplicada."],["Prescrição executória","Pressupõe pretensão de executar a sanção e observa a pena aplicada e os marcos legais."]],"advanced":[["Lei 15.438/2026","A ampliação para doze meses é especial e não transforma todo prazo decadencial penal em anual."],["Súmula 438/STJ","Não se admite prescrição pela pena hipotética."],["Perdão judicial","A sentença que o concede não é considerada para reincidência, conforme art. 120."]],"editalModule":"pen-m07","ankiDeck":"05 DIREITO PENAL::07 AÇÃO PENAL, PUNIBILIDADE E PRESCRIÇÃO","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p8","num":8,"title":"Crimes contra a pessoa","subtitle":"CP, arts. 121 a 154-B","topics":["pen-m08"],"read":"CP, arts. 121 a 154-B; Leis 14.994/2024, 15.384/2026 e 15.455/2026.","read_focus":["Homicídio, feminicídio autônomo e vicaricídio.","Lesões corporais, inclusive violência doméstica.","Crimes de perigo, rixa, honra, liberdade individual e segredos.","Atenção a penas e qualificadoras alteradas recentemente."],"outline":["homicídio","induzimento ao suicídio","infanticídio","aborto","feminicídio","vicaricídio","lesão corporal","periclitação","rixa","calúnia","difamação","injúria","constrangimento ilegal","ameaça","sequestro","trabalho análogo ao escravo","tráfico de pessoas","domicílio","correspondência","segredos"],"theory":[["Vida","O título começa com homicídio e tipos especiais. Feminicídio está no art. 121-A; vicaricídio, criado em 2026, no art. 121-B."],["Integridade corporal","O art. 129 diferencia lesão simples, grave, gravíssima, seguida de morte, culposa e contextos especiais."],["Perigo e honra","Periclitação tutela vida e saúde contra exposições específicas; calúnia, difamação e injúria têm objetos e estruturas distintos."],["Liberdade individual","Constrangimento ilegal, ameaça, sequestro/cárcere, redução a condição análoga à de escravo e tráfico de pessoas exigem comparação dos verbos e fins."],["Inviolabilidades","Domicílio, correspondência e segredos encerram o título; a qualidade do agente e o meio empregado podem qualificar ou criar tipo especial."]],"advanced":[["Vicaricídio","Matar pessoa indicada no art. 121-B com fim específico de causar sofrimento, punição ou controle à mulher, no contexto doméstico: pena de 20 a 40 anos."],["Feminicídio","Questões anteriores a outubro de 2024 podem tratá-lo como qualificadora do homicídio; hoje é tipo autônomo."],["Honra","Exceção da verdade e retratação variam conforme o delito; não transporte uma regra para os três tipos."]],"editalModule":"pen-m08","ankiDeck":"05 DIREITO PENAL::08 CRIMES CONTRA A PESSOA","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p9","num":9,"title":"Crimes contra o patrimônio","subtitle":"CP, arts. 155 a 183","topics":["pen-m09"],"read":"CP, arts. 155 a 183; Lei 15.397/2026.","read_focus":["Furto, roubo e extorsão.","Apropriação indébita, estelionato, fraudes e receptação.","Imunidades dos arts. 181 a 183.","Use apenas as penas e figuras da redação vigente em 2026."],"outline":["furto","repouso noturno","furto qualificado","furto eletrônico","roubo","roubo impróprio","majorantes","latrocínio","extorsão","extorsão mediante sequestro","usurpação","dano","apropriação indébita","estelionato","conta laranja","fraude eletrônica","receptação","receptação de animal","escusas"],"theory":[["Furto","Subtrair coisa alheia móvel. A Lei 15.397/2026 elevou a pena do caput para um a seis anos e multa e o repouso noturno passou a aumentar a pena de metade."],["Roubo","A subtração com violência ou grave ameaça tem pena-base de seis a dez anos e multa desde 2026; figuras majoradas e qualificadas exigem leitura atual."],["Estelionato","Fraude que induz ou mantém alguém em erro para vantagem ilícita. A lei atual inclui cessão de conta laranja e pena específica da fraude eletrônica."],["Receptação","Receber, adquirir, transportar, conduzir ou ocultar produto de crime exige atenção ao elemento subjetivo e à forma qualificada; penas foram atualizadas em 2026."],["Escusas","Os arts. 181 a 183 disciplinam imunidades absolutas e relativas, com exceções ligadas a violência, grave ameaça, estranho participante e vítimas protegidas."]],"advanced":[["Atualização obrigatória","Questões anteriores a maio de 2026 podem ter penas, frações ou figuras incompatíveis com a Lei 15.397."],["Roubo x extorsão","Observe se a colaboração da vítima é imprescindível para obter a vantagem."],["Estelionato x furto mediante fraude","Na fraude do estelionato, a vítima entrega o bem; no furto fraudulento, a fraude reduz a vigilância e o agente subtrai."]],"editalModule":"pen-m09","ankiDeck":"05 DIREITO PENAL::09 CRIMES CONTRA O PATRIMÔNIO","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p10","num":10,"title":"Crimes contra a fé pública","subtitle":"CP, arts. 289 a 311-A","topics":["pen-m10"],"read":"CP, arts. 289 a 311-A.","read_focus":["Moeda falsa e papéis públicos.","Falsidade material e ideológica.","Uso de documento falso.","Falsa identidade e sinais de identificação."],"outline":["moeda falsa","petrechos","papéis públicos","selo ou sinal","documento público","documento particular","falsidade ideológica","falso reconhecimento","atestado médico","uso de documento falso","supressão de documento","falsa identidade","adulteração de veículo","fraudes em certames"],"theory":[["Bem jurídico","A fé pública protege a confiança coletiva na moeda, documentos, sinais e identificações."],["Falsidade material","Recai sobre a forma ou autenticidade do documento; compare documento público, particular e equiparações."],["Falsidade ideológica","O documento é formalmente autêntico, mas declaração juridicamente relevante é omitida ou inserida falsamente com finalidade específica."],["Uso","O art. 304 pune fazer uso de documento falso nas condições legais; o falsificador que usa o próprio documento normalmente responde conforme a relação entre os fatos."],["Identidade e sinais","Falsa identidade, documento de identidade alheio e adulteração de sinal veicular possuem objetos e verbos diferentes."]],"advanced":[["Súmula 17/STJ","O falso se exaure no estelionato e é por ele absorvido quando não tem potencialidade lesiva autônoma."],["Documento público por equiparação","A equiparação do art. 297, §2º, é campo frequente de prova."],["Autodefesa","A jurisprudência distingue mentir sobre identidade de outras condutas de autodefesa; revise a Súmula 522/STJ."]],"editalModule":"pen-m10","ankiDeck":"05 DIREITO PENAL::10 CRIMES CONTRA A FÉ PÚBLICA","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p11","num":11,"title":"Crimes contra a dignidade sexual","subtitle":"CP, arts. 213 a 234-B","topics":["pen-m11"],"read":"CP, arts. 213 a 234-B; Leis 15.280/2025 e 15.353/2026.","read_focus":["Estupro e violação sexual mediante fraude.","Importunacão e assédio sexual.","Estupro de vulnerável e presunção absoluta.","Divulgação de cena e causas de aumento.","Use as penas vigentes após a Lei 15.280/2025."],"outline":["estupro","violação mediante fraude","importunação","assédio","registro não autorizado","estupro de vulnerável","corrupção de menores","satisfação de lascívia","exploração sexual","divulgação de cena","ação penal","aumentos","segredo de justiça"],"theory":[["Liberdade sexual","Os tipos dos arts. 213 a 216-B protegem autodeterminação sexual, intimidade e liberdade contra violência, fraude, importunação, abuso hierárquico e registros indevidos."],["Vulnerabilidade","No art. 217-A, a vulnerabilidade da vítima menor de quatorze anos é absoluta e não pode ser relativizada."],["Penas atuais","Desde a Lei 15.280/2025, o caput do art. 217-A prevê reclusão de dez a dezoito anos e multa; resultados lesão grave e morte têm faixas agravadas."],["Outros vulneráveis","Os arts. 218, 218-A, 218-B e 218-C também receberam penas mais severas; compare verbo, vítima e finalidade."],["Disposições gerais","Ação penal, aumentos e segredo de justiça completam o regime do título."]],"advanced":[["Lei 15.353/2026","Consentimento, experiência sexual anterior e gravidez não afastam as penas do art. 217-A."],["Questões antigas","Gabaritos anteriores a dezembro de 2025 podem trazer penas revogadas; o alerta do banco preserva o item sem induzir revisão errada."],["Erro de tipo","Em casos concretos sobre idade, a discussão deve ser separada da impossibilidade de relativizar juridicamente a vulnerabilidade."]],"editalModule":"pen-m11","ankiDeck":"05 DIREITO PENAL::11 CRIMES CONTRA A DIGNIDADE SEXUAL","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p12","num":12,"title":"Crimes contra a Administração Pública","subtitle":"CP, arts. 312 a 359, exceto recortes autônomos dos módulos 16 e 17","topics":["pen-m12"],"read":"CP, arts. 312 a 359; art. 338-A incluído pela Lei 15.280/2025.","read_focus":["Crimes funcionais próprios e impróprios.","Peculato, concussão, corrupção e prevaricação.","Crimes de particular contra a Administração.","Administração da Justiça.","Conceito penal de funcionário público."],"outline":["peculato","inserção de dados","extravio","emprego irregular","concussão","corrupção passiva","prevaricação","condescendência","advocacia administrativa","violência arbitrária","abandono","sigilo funcional","funcionário público","usurpação","resistência","desobediência","desacato","tráfico de influência","corrupção ativa","contrabando","descaminho","sonegação previdenciária","administração da justiça","descumprimento de protetiva"],"theory":[["Crimes funcionais","O agente público integra o tipo; no art. 327, o conceito penal é amplo e alcança quem exerce função ainda que transitoriamente ou sem remuneração."],["Peculato e concussão","No peculato, compare posse funcional, desvio, subtração facilitada e erro alheio. Na concussão, o verbo nuclear é exigir."],["Corrupções","Corrupção passiva e ativa são delitos autônomos; solicitar/receber/aceitar promessa não se confunde com oferecer/prometer."],["Particular e Justiça","Resistência, desobediência, desacato e tráfico de influência antecedem os crimes contra a Administração da Justiça."],["Art. 338-A","Descumprir decisão judicial que defere medida protetiva de urgência em crimes sexuais é tipo incluído em 2025, com pena de dois a cinco anos e multa."]],"advanced":[["Comunicação da elementar","A condição de funcionário pode comunicar-se ao particular que a conhece, por ser elementar."],["Concussão x corrupção","Exigir aponta para concussão; solicitar, receber ou aceitar promessa, para corrupção passiva."],["Descumprimento de protetiva","A configuração do art. 338-A independe de o juiz que deferiu a medida ter competência civil ou criminal."]],"editalModule":"pen-m12","ankiDeck":"05 DIREITO PENAL::12 CRIMES CONTRA A ADMINISTRAÇÃO PÚBLICA","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p13","num":13,"title":"Abuso de autoridade","subtitle":"Lei 13.869/2019","topics":["pen-m13"],"read":"Lei 13.869/2019, arts. 1º a 38.","read_focus":["Finalidade específica do art. 1º, §1º.","Conceito amplo de agente público.","Ação pública incondicionada.","Efeitos da condenação não automáticos nos casos legais.","Tipos penais e elementares como manifesta desconformidade, sem justa causa e indevidamente."],"outline":["sujeito ativo","dolo específico","divergência interpretativa","ação penal","efeitos","restritivas","independência de instâncias","prisão ilegal","condução coercitiva","comunicação de prisão","constrangimento","violência institucional","identificação","interrogatório noturno","entrevista com advogado","invasão","fraude processual","prova ilícita","investigação sem indício"],"theory":[["Elemento subjetivo","Os crimes exigem finalidade específica de prejudicar ou beneficiar, ou mero capricho ou satisfação pessoal."],["Divergência","Divergência na interpretação da lei ou na avaliação de fatos e provas, isoladamente, não configura abuso."],["Sujeito ativo","Qualquer agente público, servidor ou não, de qualquer Poder ou ente, inclusive quem exerce função transitoriamente ou sem remuneração."],["Ação e efeitos","A ação é pública incondicionada; perda/inabilitação dependem das condições legais, não são automáticas e exigem motivação."],["Tipos","A lei usa elementos normativos fortes; a prova costuma omitir manifesta ilegalidade, ausência de justa causa ou finalidade específica."]],"advanced":[["Efeitos","Inabilitação e perda exigem reincidência em abuso e declaração motivada."],["Mandado domiciliar","O art. 22 trabalha com ingresso fora das condições legais e horário específico para cumprimento do mandado."],["Independência","A absolvição penal repercute nas outras esferas quando reconhece inexistência do fato, negativa de autoria ou justificante nos limites legais."]],"editalModule":"pen-m13","ankiDeck":"05 DIREITO PENAL::13 ABUSO DE AUTORIDADE - LEI 13.869","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p14","num":14,"title":"Lavagem de dinheiro","subtitle":"Lei 9.613/1998","topics":["pen-m14"],"read":"Lei 9.613/1998 compilada; Lei 15.358/2026.","read_focus":["Ocultar ou dissimular bens, direitos ou valores provenientes de infração penal.","Não existe rol fechado de crimes antecedentes.","Autonomia processual e indícios do antecedente.","Medidas assecuratórias e alienação antecipada.","Deveres preventivos e Coaf.","Destinação de ativos conforme competência após a Lei 15.358/2026."],"outline":["tipo básico","infração antecedente","equiparados","tentativa","aumento","colaboração","autonomia","competência","denúncia","medidas assecuratórias","alienação antecipada","efeitos","destinação","cooperação","pessoas obrigadas","cadastro","registros","comunicação","Coaf"],"theory":[["Tipo e antecedente","Ocultar ou dissimular natureza, origem, localização, disposição, movimentação ou propriedade de bens, direitos ou valores provenientes, direta ou indiretamente, de infração penal."],["Autonomia","O processo e julgamento independem do processo e julgamento do antecedente, embora a denúncia deva vir com indícios suficientes de sua existência."],["Medidas patrimoniais","Bens do investigado, acusado ou interpostas pessoas podem sofrer medidas assecuratórias; alienação antecipada preserva valor quando cabível."],["Destinação atual","A Lei 15.358/2026 passou a distinguir incorporação em favor da União ou do Estado/DF conforme a competência do processo."],["Prevenção","Pessoas obrigadas devem identificar clientes, manter registros e comunicar operações; o Coaf atua em inteligência financeira e sanções administrativas nos limites legais."]],"advanced":[["Autolavagem","O agente do antecedente pode responder também por lavagem quando pratica atos autônomos de ocultação ou dissimulação."],["Dolo","A mera fruição do produto do crime não substitui a prova do ato de ocultar ou dissimular."],["Atualização 2026","Questões antigas sobre perda e depósitos exigem conferência da redação dada pela Lei 15.358."]],"editalModule":"pen-m14","ankiDeck":"05 DIREITO PENAL::14 LAVAGEM DE DINHEIRO - LEI 9.613","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p15","num":15,"title":"Disposições constitucionais e súmulas STF/STJ","subtitle":"CF, art. 5º; súmulas penais do STF e STJ","topics":["pen-m15"],"read":"CF, art. 5º, XXXIX a LXVIII; súmulas penais indicadas.","read_focus":["Legalidade e retroatividade benéfica.","Pessoalidade e individualização.","Penas vedadas e direitos do preso.","Devido processo, presunção de inocência e habeas corpus.","Súmulas 11, 24 e 711/STF; 17, 231, 444, 522 e 588/STJ."],"outline":["CF art. 5 XXXIX","retroatividade","racismo","tortura e hediondos","ação de grupos armados","pessoalidade","individualização","penas vedadas","estabelecimentos","integridade do preso","devido processo","contraditório","prova ilícita","presunção de inocência","prisão","habeas corpus","súmulas vinculantes","súmulas STF","súmulas STJ"],"theory":[["Garantias penais","Legalidade, irretroatividade gravosa, pessoalidade e individualização formam o núcleo constitucional material."],["Penas","A CF admite privação/restrição de liberdade, perda de bens, multa, prestação social e suspensão/interdição; veda morte salvo guerra declarada, perpétua, trabalhos forçados, banimento e cruéis."],["Processo e liberdade","Devido processo, contraditório, ampla defesa, inadmissibilidade de prova ilícita, presunção de inocência e regras de prisão dialogam com o direito penal."],["STF","SV 11 limita algemas; SV 24 trata do crime material tributário antes do lançamento definitivo; Súmula 711 disciplina lei mais grave em crime continuado ou permanente."],["STJ","Súmulas 17, 231, 444, 522 e 588 condensam entendimentos recorrentes sobre falso, atenuante, antecedentes, falsa identidade e violência doméstica."]],"advanced":[["Súmula 444/STJ","Inquéritos e ações penais em curso não podem agravar a pena-base."],["Súmula 231/STJ","A incidência de atenuante não conduz abaixo do mínimo legal segundo o enunciado vigente."],["Súmula 588/STJ","Crime ou contravenção contra mulher com violência ou grave ameaça no ambiente doméstico impede substituição por restritiva."]],"editalModule":"pen-m15","ankiDeck":"05 DIREITO PENAL::15 CONSTITUIÇÃO E SÚMULAS STF-STJ","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p16","num":16,"title":"Crimes em licitações e contratos","subtitle":"CP, arts. 337-E a 337-P; Lei 14.133/2021","topics":["pen-m16"],"read":"Lei 14.133/2021, art. 178; CP, arts. 337-E a 337-P.","read_focus":["Contratação direta ilegal.","Frustração competitiva e patrocínio indevido.","Irregularidade contratual, perturbação, sigilo e afastamento.","Fraude, inidoneidade, cadastro e omissão de projetista.","Multa mínima de 2% do art. 337-P."],"outline":["337-E","337-F","337-G","337-H","337-I","337-J","337-K","337-L","337-M","337-N","337-O","337-P"],"theory":[["Sistema","A Lei 14.133 inseriu no Código Penal o Capítulo II-B do Título XI; os crimes não ficam apenas na lei administrativa."],["Fase de contratação","337-E pune contratação direta ilegal; 337-F protege competição; 337-G trata do patrocínio de interesse privado que produz contratação judicialmente invalidada."],["Procedimento e contrato","337-H a K abrangem modificação/pagamento irregular, perturbação, sigilo e afastamento de licitante."],["Fraudes e cadastros","337-L tipifica fraudes em prejuízo da Administração; 337-M a O tratam de inidôneo, impedimento cadastral e omissão grave de projetista."],["Multa","Art. 337-P: metodologia do CP e piso de 2% do valor do contrato licitado ou celebrado por contratação direta."]],"advanced":[["337-F","Exige intuito de obter vantagem decorrente da adjudicação para si ou terceiro."],["337-K","Além de afastar, pune tentar afastar; a pena vem sem prejuízo da violência."],["337-O","Se praticado para obter benefício direto ou indireto, próprio ou alheio, a pena do caput é aplicada em dobro."]],"editalModule":"pen-m16","ankiDeck":"05 DIREITO PENAL::16 CRIMES EM LICITAÇÕES E CONTRATOS","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"},{"id":"p17","num":17,"title":"Responsabilidade, finanças públicas e LRF","subtitle":"Lei 1.079/1950; Lei 10.028/2000; LC 101/2000; CP, arts. 359-A a 359-H","topics":["pen-m17"],"read":"Lei 1.079/1950; Lei 10.028/2000; LC 101/2000; CP, arts. 359-A a 359-H.","read_focus":["Natureza e hipóteses da Lei 1.079.","A Lei 10.028 acrescentou crimes contra as finanças ao CP e infrações administrativas à LRF.","Operação de crédito, inscrição em restos, despesa e garantia.","Regras fiscais da LC 101: transparência, renúncia, despesa e final de mandato."],"outline":["crime de responsabilidade","Presidente da República","Ministros","STF e PGR","Governadores","prefeitos","Lei 10.028","359-A","359-B","359-C","359-D","359-E","359-F","359-G","359-H","LRF art. 1","metas","receita","renúncia","despesa","pessoal","dívida","operação de crédito","restos a pagar","transparência","fiscalização"],"theory":[["Lei 1.079/1950","Define infrações político-administrativas de altas autoridades e disciplina seu processo, sem se confundir automaticamente com crimes comuns do Código Penal."],["Lei 10.028/2000","A Lei de Crimes Fiscais inseriu os arts. 359-A a 359-H no CP e acrescentou infrações administrativas ligadas à gestão fiscal."],["Crimes fiscais","Operação de crédito ilegal, inscrição irregular em restos, assunção de obrigação e prestação de garantia são núcleos centrais."],["LRF","Responsabilidade fiscal pressupõe ação planejada e transparente para prevenir riscos e corrigir desvios capazes de afetar as contas públicas."],["Final de mandato","O art. 42 da LRF veda, nos dois últimos quadrimestres, obrigação que não possa ser integralmente cumprida no mandato ou sem caixa suficiente para o restante."]],"advanced":[["Instâncias","Responsabilização política, penal, civil e administrativa pode coexistir nos limites constitucionais e legais."],["Norma penal em branco","Crimes fiscais frequentemente exigem compreender autorizações, limites e condições definidos no direito financeiro."],["LRF e prova penal","Nem toda infração fiscal é automaticamente crime; identifique o tipo penal e seus elementos."]],"editalModule":"pen-m17","ankiDeck":"05 DIREITO PENAL::17 RESPONSABILIDADE, FINANÇAS PÚBLICAS E LRF","auditStatus":"alinhado-ao-edital-tjce-cargo-16-v6632"}];

const PENAL_STORAGE_KEY='penal_tjce_fcc_guided_v32';
const PENAL_LEGACY_STORAGE_KEY='penal_tjce_fcc_guided_v31';
const PENAL_LETTERS=['A','B','C','D','E'];
let penalSession=null;

function penalFresh(){return {answers:{},weeks:{},lastWeek:'w1'}}
function penalState(){
 try{
   const raw=localStorage.getItem(PENAL_STORAGE_KEY)||localStorage.getItem(PENAL_LEGACY_STORAGE_KEY)||'{}';
   return {...penalFresh(),...JSON.parse(raw)};
 }catch(e){return penalFresh()}
}
function penalSave(st){localStorage.setItem(PENAL_STORAGE_KEY,JSON.stringify(st))}
function penalWeekState(id){
 const st=penalState(),x=st.weeks?.[id]||{};
 ['diagnostic','reading','theory','intermediate','deep','fixation'].forEach(k=>{if(typeof x[k]!=='boolean')x[k]=false});
 return x;
}
function penalUpdateWeek(id,patch){
 const st=penalState();st.weeks=st.weeks||{};st.weeks[id]={...(st.weeks[id]||{}),...patch};st.lastWeek=id;penalSave(st);renderAll();
}
function penalWeekPct(w){
 const st=penalWeekState(w.id),keys=['diagnostic','reading','theory','intermediate','deep','fixation'];
 return Math.round(keys.filter(k=>st[k]).length/keys.length*100);
}
function penalPool(w){return PENAL_QUESTIONS.filter(q=>w.topics.includes(q.t))}
function penalStats(){
 const st=penalState();let answered=0,correct=0,wrongIds=[];
 PENAL_QUESTIONS.forEach(q=>{
   const a=st.answers?.[q.id];
   if(a?.attempts){answered++;if(a.lastCorrect)correct++;if(a.everWrong&&!a.lastCorrect)wrongIds.push(q.id)}
 });
 return {answered,correct,wrongIds,accuracy:answered?Math.round(correct/answered*1000)/10:0};
}
function penalModuleErrors(w){const ids=new Set(penalStats().wrongIds);return penalPool(w).filter(q=>ids.has(q.id))}
function penalModuleOpenKey(id){return `central-v6:penal-open:${id}`}
function togglePenalModule(id){
 const el=document.querySelector(`.cf-module[data-cf="${id}"]`);if(!el)return;
 const open=!el.classList.contains('open');el.classList.toggle('open',open);localStorage.setItem(penalModuleOpenKey(id),open?'1':'0');
 if(open){const w=PENAL_WEEKS.find(x=>x.id===id);if(w)saveLast({penalWeek:id,title:`Penal • Módulo ${w.num} • ${w.title}`,at:Date.now()})}
}
function openPenalLast(id){
 openHome();localStorage.setItem('central-v6:open:penal','1');localStorage.setItem(penalModuleOpenKey(id),'1');
 setTimeout(()=>{renderSubjects();document.querySelector(`.cf-module[data-cf="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})},40);
}
function penalDeterministic(list,count,seed){
 if(!list.length)return[];
 const st=penalState(),unseen=list.filter(q=>!st.answers?.[q.id]?.attempts),seen=list.filter(q=>st.answers?.[q.id]?.attempts),src=[...unseen,...seen];
 let h=2166136261;for(const c of String(seed))h=(Math.imul(h^c.charCodeAt(0),16777619))>>>0;
 return src.map((q,i)=>({q,k:(h^(Math.imul(i+1,2654435761)))>>>0})).sort((a,b)=>a.k-b.k).slice(0,Math.min(count,src.length)).map(x=>x.q);
}
function penalOptionOrder(q,mode){
 const st=penalState(),a=[0,1,2,3,4];let h=2166136261;
 const seed=q.id+':'+(st.answers?.[q.id]?.attempts||0)+':'+mode;
 for(const c of seed)h=(Math.imul(h^c.charCodeAt(0),16777619))>>>0;
 for(let i=a.length-1;i>0;i--){h=(Math.imul(h^(h>>>13),1597334677))>>>0;const j=h%(i+1);[a[i],a[j]]=[a[j],a[i]]}
 return a;
}
function penalSourceKind(q){return q.real===false?'AUTORAL • cobertura do edital':'FCC real'}
function penalLegalUpdate(q){
 const raw=((q.r||'')+' '+(q.source||'')),ys=raw.match(/\b20\d{2}\b/g),y=ys?Math.max(...ys.map(Number)):null;
 if(q.update)return q.update;
 if(q.real===false)return '';
 const x=((q.q||'')+' '+(q.o||[]).join(' ')).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 if(q.moduleId==='pen-m07'&&(y||0)<2026&&/(violencia domestica|mulher|maria da penha)/.test(x)&&/(decad|representa|queixa|seis meses|6 meses)/.test(x))return 'Lei 15.438/2026: prazo decadencial especial de 12 meses na violência doméstica e familiar contra a mulher.';
 if(q.moduleId==='pen-m08'&&(y||0)<2026&&/(feminic|homic|lesao corporal|violencia domestica|pena)/.test(x))return 'Confira a redação atual dos crimes contra a pessoa, inclusive feminicídio autônomo e vicaricídio.';
 if(q.moduleId==='pen-m09'&&(y||0)<2026&&/(furto|roubo|estelionato|receptacao|fraude eletronica|repouso noturno|conta laranja|pena)/.test(x))return 'Lei 15.397/2026 alterou penas e figuras patrimoniais. O gabarito exibido é o histórico da prova.';
 if(q.moduleId==='pen-m11'&&(y||0)<2026&&/(vulneravel|217|218|pena|consentimento|experiencia sexual)/.test(x))return 'Leis 15.280/2025 e 15.353/2026 alteraram penas e confirmaram vulnerabilidade absoluta.';
 if(q.moduleId==='pen-m14'&&(y||0)<2026&&/(perda|bens|valores|deposito|destinacao|uniao|estado)/.test(x))return 'Lei 15.358/2026 alterou a destinação dos ativos conforme a competência.';
 return '';
}
const PENAL_ANKI={"p1":"05 DIREITO PENAL::01 PRINCÍPIOS, INTERPRETAÇÃO, ANALOGIA E CONFLITO APARENTE","p2":"05 DIREITO PENAL::02 APLICAÇÃO DA LEI PENAL NO TEMPO E NO ESPAÇO","p3":"05 DIREITO PENAL::03 ILICITUDE","p4":"05 DIREITO PENAL::04 CULPABILIDADE","p5":"05 DIREITO PENAL::05 CONCURSO DE PESSOAS","p6":"05 DIREITO PENAL::06 PENAS - ESPÉCIES E COMINAÇÃO","p7":"05 DIREITO PENAL::07 AÇÃO PENAL, PUNIBILIDADE E PRESCRIÇÃO","p8":"05 DIREITO PENAL::08 CRIMES CONTRA A PESSOA","p9":"05 DIREITO PENAL::09 CRIMES CONTRA O PATRIMÔNIO","p10":"05 DIREITO PENAL::10 CRIMES CONTRA A FÉ PÚBLICA","p11":"05 DIREITO PENAL::11 CRIMES CONTRA A DIGNIDADE SEXUAL","p12":"05 DIREITO PENAL::12 CRIMES CONTRA A ADMINISTRAÇÃO PÚBLICA","p13":"05 DIREITO PENAL::13 ABUSO DE AUTORIDADE - LEI 13.869","p14":"05 DIREITO PENAL::14 LAVAGEM DE DINHEIRO - LEI 9.613","p15":"05 DIREITO PENAL::15 CONSTITUIÇÃO E SÚMULAS STF-STJ","p16":"05 DIREITO PENAL::16 CRIMES EM LICITAÇÕES E CONTRATOS","p17":"05 DIREITO PENAL::17 RESPONSABILIDADE, FINANÇAS PÚBLICAS E LRF"};
function penalResKey(id){return `central-v6:penal-res:${id}`}
function penalResources(id){try{return JSON.parse(localStorage.getItem(penalResKey(id))||'{}')}catch(e){return {}}}
function editPenalResource(id,kind){
 const r=penalResources(id),v=prompt(`Cole o link de ${kind==='tec'?'TEC Concursos':'QConcursos'}:`,r[kind]||'https://');
 if(v===null)return;const value=v.trim();if(!value){r[kind]='';localStorage.setItem(penalResKey(id),JSON.stringify(r));renderSubjects();return}
 const u=safeUrl(value);if(!u){alert('Link inválido.');return}r[kind]=u;localStorage.setItem(penalResKey(id),JSON.stringify(r));renderSubjects();
}
function openPenalResource(id,kind){const r=penalResources(id),u=safeUrl(r[kind]);if(u)openExternalUrl(u);else editPenalResource(id,kind)}
function penalNoteKey(id){return `central-v6:penal-note:${id}`}
function savePenalNote(id){const el=document.getElementById(`cf-note-${id}`);if(!el)return;localStorage.setItem(penalNoteKey(id),el.value);alert('Anotação salva.')}
function penalStep(n,title,desc,done,body){
 return `<section class="cf-step ${done?'done':''}"><div class="cf-step-head"><div class="cf-step-no">${done?'✓':n}</div><div class="cf-step-copy"><b>${title}</b><small>${desc}</small></div></div><div class="cf-step-body">${body}</div></section>`;
}
function renderPenalMaster(){
 const st=penalStats(),real=PENAL_QUESTIONS.filter(q=>q.real!==false).length,ined=PENAL_QUESTIONS.length-real;
 return `<div class="cf-master-tools">
   <button onclick="renderPenalErrorPanel()">⚠ Erros ${st.wrongIds.length?`(${st.wrongIds.length})`:''}</button>
   <button onclick="exportPenalProgress()">💾 Backup</button>
   <button onclick="document.getElementById('penal-import-file').click()">↥ Restaurar</button>
   <input class="cf-file" id="penal-import-file" type="file" accept=".json,application/json" onchange="importPenalProgress(this)">
 </div>
 <div class="cf-resource-box" style="margin:12px 0 14px;border-color:#315c54;background:linear-gradient(135deg,rgba(49,92,84,.14),rgba(49,92,84,.04))">
   <h4 style="margin:0 0 6px">Decorando Penal atualizado</h4>
   <div class="muted small" style="margin-bottom:10px"><b style="color:inherit">1.763 questões únicas</b> organizadas por assunto e artigo do Código Penal, incluindo 1.674 questões novas do PDF auditado.</div>
   <div class="cf-actions"><button class="cf-btn primary" onclick="openLeiSecaEnxuta(null,'penal')">Abrir as 1.763 questões</button></div>
 </div>
 <div class="cf-metrics">
   <div class="cf-metric"><small>Banco do curso</small><b>${PENAL_QUESTIONS.length}</b></div>
   <div class="cf-metric"><small>Respondidas</small><b>${st.answered}</b></div>
   <div class="cf-metric"><small>Aproveitamento</small><b>${st.answered?st.accuracy+'%':'—'}</b></div>
   <div class="cf-metric"><small>Erros pendentes</small><b>${st.wrongIds.length}</b></div>
 </div>
 <div id="penal-session-host"></div>
 <div id="penal-errors-host"></div>
 <div class="cf-modules">${PENAL_WEEKS.map(renderPenalModule).join('')}</div>`;
}
function renderPenalModule(w){
 const ws=penalWeekState(w.id),pct=penalWeekPct(w),pool=penalPool(w),real=pool.filter(q=>q.real!==false),ined=pool.filter(q=>q.real===false),errors=penalModuleErrors(w);
 const open=localStorage.getItem(penalModuleOpenKey(w.id))==='1';
 const diag=Math.min(5,real.length),inter=Math.min(8,real.length),finalN=Math.min(15,real.length),extra=real.length,r=penalResources(w.id),tecAuto=(typeof window.tecContextButtons==='function'?window.tecContextButtons(w.id,'cf-btn'):'');
 return `<section class="cf-module ${open?'open':''}" data-cf="${w.id}">
   <button class="cf-module-head" onclick="togglePenalModule('${w.id}')">
     <span class="cf-module-no">MÓDULO ${w.num}</span><span class="cf-module-title">${esc(w.title)}</span>
     <span class="cf-module-stat">${pct}% • ${real.length} FCC reais + ${ined.length} autorais</span><span class="chev">⌄</span>
   </button>
   <div class="cf-module-body">
     <div class="cf-module-bar"><span style="width:${pct}%"></span></div>
     <div class="cf-subtitle">${esc(w.subtitle)}</div>
     <details class="cf-syllabus"><summary>Matriz do edital • ${w.outline.length} pontos</summary><div class="cf-micro-grid">${w.outline.map(x=>`<span class="cf-micro">${esc(x)}</span>`).join('')}</div></details>
     <div class="cf-steps">
       ${penalStep(1,'Diagnóstico','Questões FCC antes da teoria.',ws.diagnostic,real.length?`<button class="cf-btn primary" onclick="startPenalQuiz('${w.id}','diagnostic',${diag})">${ws.diagnostic?'Refazer diagnóstico':'Começar '+diag+' FCC'}</button>`:`<span class="muted small">Sem questões reais suficientes.</span>`)}
       ${penalStep(2,'Leitura orientada','Dispositivos e pontos para observar na legislação penal.',ws.reading,`<div class="cf-reading"><strong>${esc(w.read)}</strong><ul>${w.read_focus.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="cf-actions"><button class="cf-btn primary" onclick="openLeiSecaEnxuta(null,'penal','${w.editalModule}')">📖 Decorando deste módulo</button><button class="cf-btn" onclick="openVadeMecum(null,'cp')">Abrir Vade Mecum Penal</button><button class="cf-btn ${ws.reading?'good':''}" onclick="penalUpdateWeek('${w.id}',{reading:${!ws.reading}})">${ws.reading?'✓ Concluída':'Marcar concluída'}</button></div>`)}
       ${penalStep(3,'Teoria nuclear','Base completa antes da segunda bateria.',ws.theory,`<div class="cf-theory-grid">${w.theory.map((t,i)=>`<details class="cf-theory" ${i===0?'open':''}><summary>${esc(t[0])}</summary><div class="cf-theory-text">${esc(t[1])}</div></details>`).join('')}</div><div class="cf-actions"><button class="cf-btn ${ws.theory?'good':''}" onclick="penalUpdateWeek('${w.id}',{theory:${!ws.theory}})">${ws.theory?'✓ Teoria concluída':'Marcar teoria concluída'}</button></div>`)}
       ${penalStep(4,'Questões intermediárias','Bateria curta depois da teoria.',ws.intermediate,real.length?`<button class="cf-btn primary" onclick="startPenalQuiz('${w.id}','intermediate',${inter})">${ws.intermediate?'Refazer '+inter+' FCC':'Fazer '+inter+' FCC'}</button>`:`<span class="muted small">Sem fila real suficiente.</span>`)}
       ${penalStep(5,'Aprofundamento FCC','Distinções, exceções e pegadinhas de nível mais alto.',ws.deep,`<div class="cf-advanced-grid">${w.advanced.map(t=>`<div class="cf-advanced"><b>${esc(t[0])}</b><div>${esc(t[1])}</div></div>`).join('')}</div><div class="cf-actions"><button class="cf-btn ${ws.deep?'good':''}" onclick="penalUpdateWeek('${w.id}',{deep:${!ws.deep}})">${ws.deep?'✓ Aprofundamento concluído':'Marcar aprofundamento concluído'}</button></div>`)}
       ${penalStep(6,'Bateria final FCC','Misture literalidade, exceções e casos concretos.',ws.fixation,`<div class="cf-actions">${real.length?`<button class="cf-btn primary" onclick="startPenalQuiz('${w.id}','fixation',${finalN})">FCC real • ${finalN}</button>${extra>finalN?`<button class="cf-btn" onclick="startPenalQuiz('${w.id}','extra',${extra})">Banco completo • ${extra}</button>`:''}`:''}${ined.length?`<button class="cf-btn" onclick="startPenalQuiz('${w.id}','coverage',${Math.min(15,ined.length)})">Cobertura inédita • ${Math.min(15,ined.length)}</button>`:''}</div><div class="cf-coverage">${real.length} questões FCC reais + ${ined.length} autorais neste módulo.</div>`)}
       ${penalStep(7,'Revisão de erros',errors.length?`${errors.length} erro(s) pendente(s) neste módulo.`:'Nenhum erro pendente.',errors.length===0,errors.length?`<button class="cf-btn bad" onclick="startPenalQuiz('${w.id}','errors',999)">Refazer ${errors.length} erro(s)</button>`:`<span class="muted small">A fila fica vazia quando a questão é acertada novamente.</span>`)}
     </div>
     <details class="cf-resources"><summary class="muted small" style="cursor:pointer">Recursos do módulo • TEC/QC, Anki e anotações</summary>
       <div class="cf-resource-grid" style="margin-top:8px">
         <div class="cf-resource-box"><h4>Questões externas</h4><div class="cf-actions">${tecAuto}${r.tec?`<button class="cf-btn" onclick="openPenalResource('${w.id}','tec')">TEC personalizado ↗</button>`:(tecAuto?'':`<button class="cf-btn" onclick="openPenalResource('${w.id}','tec')">+ TEC</button>`)}<button class="cf-btn" onclick="openPenalResource('${w.id}','qc')">${r.qc?'Abrir QC':'+ QC'}</button></div></div>
         <div class="cf-resource-box"><h4>Decorando a Lei</h4><button class="cf-btn" onclick="openLeiSecaEnxuta(null,'penal','${w.editalModule}')">Abrir artigos deste módulo</button></div>
         <div class="cf-resource-box"><h4>Anki</h4>${PENAL_ANKI[w.id]?`<button class="cf-btn" onclick="openAnkiDeck('${escJs(PENAL_ANKI[w.id])}','${escJs(w.title)}')">Abrir baralho</button>`:'<span class="muted small">Sem subbaralho específico mapeado.</span>'}</div>
         <div class="cf-resource-box" style="grid-column:1/-1"><h4>Anotação</h4><textarea class="cf-notes" id="cf-note-${w.id}" placeholder="Regra, artigo, pegadinha ou dúvida...">${esc(localStorage.getItem(penalNoteKey(w.id))||'')}</textarea><div class="cf-actions"><button class="cf-btn" onclick="savePenalNote('${w.id}')">Salvar anotação</button></div></div>
       </div>
     </details>
   </div>
 </section>`;
}
function startPenalQuiz(id,mode,count){
 const w=PENAL_WEEKS.find(x=>x.id===id);if(!w)return;
 let list=penalPool(w),st=penalState();
 if(mode==='errors')list=list.filter(q=>st.answers?.[q.id]?.everWrong&&!st.answers?.[q.id]?.lastCorrect);
 else if(mode==='coverage')list=list.filter(q=>q.real===false);
 else {const real=list.filter(q=>q.real!==false);if(real.length)list=real}
 if(!list.length){alert('Não há questões nessa fila.');return}
 list=penalDeterministic(list,Math.min(count,list.length),id+mode+Object.keys(st.answers||{}).length);
 penalSession={week:w,mode,list,index:0,score:0,errors:[],answered:false,order:null};
 localStorage.setItem('central-v6:open:penal','1');localStorage.setItem(penalModuleOpenKey(id),'1');
 renderPenalQuestion();
}
function penalModeName(mode){return ({diagnostic:'Diagnóstico',intermediate:'Questões intermediárias',fixation:'Bateria final FCC',extra:'Bateria extra',coverage:'Cobertura inédita',errors:'Revisão de erros'})[mode]||'Questões'}
function renderPenalQuestion(){
 if(!penalSession)return;const host=document.getElementById('penal-session-host');if(!host)return;
 const q=penalSession.list[penalSession.index];penalSession.answered=false;penalSession.order=penalOptionOrder(q,penalSession.mode);
 const legal=penalLegalUpdate(q);
 host.innerHTML=`<section class="cf-session">
   <div class="cf-session-head"><div><b>${penalModeName(penalSession.mode)} • Módulo ${penalSession.week.num}</b><br><span class="muted small">${esc(penalSession.week.title)}</span></div><button class="pt-inline-close" onclick="closePenalSession()">✕ fechar</button></div>
   <div class="cf-session-body">
     <div class="cf-qtop"><span>${penalSession.index+1}/${penalSession.list.length}</span><span>${penalSourceKind(q)}</span></div>
     <div class="cf-qbar"><span style="width:${((penalSession.index)/penalSession.list.length)*100}%"></span></div>
     <article class="cf-question">
       <div class="cf-qmeta"><span class="cf-chip">${penalSourceKind(q)}</span><span class="cf-chip">${esc(q.subject||penalSession.week.title)}</span>${legal?'<span class="cf-chip">⚠ atualização</span>':''}</div>
       <h3>${esc(q.q)}</h3>
       <div class="cf-options">${penalSession.order.map((orig,display)=>`<div class="cf-option-row"><button class="cf-option" data-cf-opt="${orig}" onclick="answerPenalQuestion(${orig})"><span class="cf-letter">${PENAL_LETTERS[display]}</span><span>${esc(q.o[orig])}</span></button><button class="cf-strike" data-cf-strike="${orig}" onclick="togglePenalStrike(${orig})">S̶</button></div>`).join('')}</div>
       <div id="cf-feedback"></div><div class="cf-actions" style="justify-content:flex-end"><button id="cf-next" class="cf-btn primary hidden" onclick="nextPenalQuestion()">${penalSession.index+1===penalSession.list.length?'Ver resultado':'Próxima questão'}</button></div>
     </article>
   </div>
 </section>`;
 host.scrollIntoView({behavior:'smooth',block:'start'});
}
function togglePenalStrike(i){
 if(!penalSession||penalSession.answered)return;
 document.querySelector(`[data-cf-opt="${i}"]`)?.classList.toggle('struck');
 document.querySelector(`[data-cf-strike="${i}"]`)?.classList.toggle('active');
}
function answerPenalQuestion(i){
 if(!penalSession||penalSession.answered)return;penalSession.answered=true;
 const q=penalSession.list[penalSession.index],ok=i===q.a,st=penalState(),prev=st.answers?.[q.id]||{attempts:0,everWrong:false,lastCorrect:false};
 prev.attempts++;prev.lastCorrect=ok;prev.everWrong=prev.everWrong||!ok;prev.lastAt=Date.now();st.answers=st.answers||{};st.answers[q.id]=prev;penalSave(st);
 if(ok)penalSession.score++;else penalSession.errors.push(q.id);
 document.querySelectorAll('[data-cf-opt]').forEach(b=>{const orig=Number(b.dataset.penalOpt);b.disabled=true;if(orig===q.a)b.classList.add('correct');if(orig===i&&!ok)b.classList.add('wrong')});
 document.querySelectorAll('[data-cf-strike]').forEach(b=>b.disabled=true);
 const correctDisplay=penalSession.order.indexOf(q.a),legal=penalLegalUpdate(q),fb=document.getElementById('cf-feedback');
 const perAlt=Array.isArray(q.oe)?`<details style="margin-top:8px"><summary style="cursor:pointer;font-weight:800">Análise das alternativas</summary><div style="margin-top:6px">${penalSession.order.map((orig,disp)=>`<div style="border-top:1px solid rgba(255,255,255,.08);padding:6px 0"><b>${PENAL_LETTERS[disp]} • ${orig===q.a?'CORRETA':'ERRADA'}</b><br>${esc(q.oe[orig]||'')}</div>`).join('')}</div></details>`:'';
 fb.className=`cf-feedback ${ok?'good':'bad'}`;fb.innerHTML=`<b>${ok?'Correto.':'Incorreto. Gabarito: '+PENAL_LETTERS[correctDisplay]}</b><div style="margin-top:5px">${esc(q.e||'Revise o ponto correspondente no módulo.')}</div>${legal?`<div class="cf-update"><b>Atualização jurídica:</b> ${esc(legal)}</div>`:''}${perAlt}<div class="cf-source">${esc(q.r||q.source||'Banco FCC')}${q.url?` • <a href="${escAttr(q.url)}" target="_blank" rel="noopener">abrir no TEC ↗</a>`:''}</div>`;
 document.getElementById('cf-next').classList.remove('hidden');renderSummary();
}
function nextPenalQuestion(){
 if(!penalSession||!penalSession.answered)return;
 if(penalSession.index+1<penalSession.list.length){penalSession.index++;renderPenalQuestion()}else finishPenalQuiz();
}
function finishPenalQuiz(){
 const sess=penalSession,w=sess.week,st=penalState();st.weeks=st.weeks||{};const ws=st.weeks[w.id]||{};
 if(sess.mode==='diagnostic')ws.diagnostic=true;if(sess.mode==='intermediate')ws.intermediate=true;if(sess.mode==='fixation')ws.fixation=true;
 st.weeks[w.id]=ws;st.lastWeek=w.id;penalSave(st);
 const total=sess.list.length,pct=Math.round(sess.score/total*100),host=document.getElementById('penal-session-host');
 host.innerHTML=`<section class="cf-session"><div class="cf-session-head"><b>${penalModeName(sess.mode)} concluído</b><button class="pt-inline-close" onclick="closePenalSession()">✕</button></div><div class="cf-session-body cf-result"><div class="cf-score">${pct}%</div><div class="cf-result-grid"><div><b>${sess.score}</b><small>acertos</small></div><div><b>${total-sess.score}</b><small>erros</small></div><div><b>${penalWeekPct(w)}%</b><small>módulo</small></div></div><div class="cf-actions" style="justify-content:center"><button class="cf-btn primary" onclick="closePenalSession();openPenalLast('${w.id}')">Voltar ao módulo</button>${sess.errors.length?`<button class="cf-btn bad" onclick="startPenalQuiz('${w.id}','errors',999)">Refazer erros</button>`:''}</div></div></section>`;
 renderAll();localStorage.setItem('central-v6:open:penal','1');localStorage.setItem(penalModuleOpenKey(w.id),'1');
 setTimeout(()=>{const h=document.getElementById('penal-session-host');if(h)h.innerHTML=host.innerHTML},0);
}
function closePenalSession(){penalSession=null;const h=document.getElementById('penal-session-host');if(h)h.innerHTML=''}
function renderPenalErrorPanel(){
 const host=document.getElementById('penal-errors-host');if(!host)return;
 const ids=new Set(penalStats().wrongIds),list=PENAL_QUESTIONS.filter(q=>ids.has(q.id));
 if(!list.length){host.innerHTML='<div class="cf-error-panel"><b>Nenhum erro pendente.</b></div>';return}
 const weak={};list.forEach(q=>{const k=q.subject||'Assunto';weak[k]=(weak[k]||0)+1});
 const top=Object.entries(weak).sort((a,b)=>b[1]-a[1]).slice(0,6);
 host.innerHTML=`<div class="cf-error-panel"><div style="display:flex;justify-content:space-between;gap:8px"><div><b>Caderno automático de erros</b><div class="muted small">${list.length} questão(ões) pendente(s)</div></div><button class="pt-inline-close" onclick="document.getElementById('penal-errors-host').innerHTML=''">✕</button></div><div class="cf-micro-grid">${top.map(([x,n])=>`<span class="cf-micro">${esc(x)} • ${n}</span>`).join('')}</div><div class="cf-actions"><button class="cf-btn bad" onclick="startPenalGlobalErrors()">Refazer todos</button></div>${PENAL_WEEKS.map(w=>{const n=penalModuleErrors(w).length;return n?`<div class="cf-error-row"><b>Módulo ${w.num} • ${esc(w.title)}</b><small>${n} erro(s)</small><div class="cf-actions"><button class="cf-btn" onclick="startPenalQuiz('${w.id}','errors',999)">Revisar módulo</button></div></div>`:''}).join('')}</div>`;
 host.scrollIntoView({behavior:'smooth',block:'start'});
}
function startPenalGlobalErrors(){
 const st=penalState(),list=PENAL_QUESTIONS.filter(q=>st.answers?.[q.id]?.everWrong&&!st.answers?.[q.id]?.lastCorrect);if(!list.length)return;
 penalSession={week:PENAL_WEEKS[0],mode:'errors',list:penalDeterministic(list,list.length,'global-errors'),index:0,score:0,errors:[],answered:false,order:null};renderPenalQuestion();
}
function exportPenalProgress(){
 const payload={app:'Penal TJCE FCC',version:'3.2-central',exportedAt:new Date().toISOString(),storageKey:PENAL_STORAGE_KEY,state:penalState()};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=`backup-penal-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);
}
async function importPenalProgress(input){
 const file=input.files?.[0];if(!file)return;
 try{const obj=JSON.parse(await file.text()),st=obj.state||obj;if(!st.answers||!st.weeks)throw new Error();if(!confirm('Restaurar este progresso de Penal?'))return;penalSave({...penalFresh(),...st});renderAll();alert('Progresso restaurado.')}catch(e){alert('Backup inválido.')}input.value='';
}


const CPC_WEEKS=[{"id":"cpc1","num":1,"title":"Normas fundamentais, fontes, aplicação e direito intertemporal","subtitle":"CPC, arts. 1º a 15; CF; LINDB","topics":["cpc-m01"],"read":"CPC, arts. 1º a 15; CF, art. 5º, XXXV, LIV, LV e LXXVIII; LINDB, arts. 4º e 5º.","read_focus":["Comece pelos arts. 1º a 12 e identifique a função de cada princípio.","Nos arts. 13 a 15, separe territorialidade, aplicação imediata e aplicação supletiva/subsidiária.","Diferencie norma processual, material e híbrida para resolver o direito intertemporal.","Fontes: Constituição, lei, precedentes, princípios, negócios processuais e integração."],"outline":["constitucionalização do processo","inafastabilidade","inércia e impulso oficial","boa-fé","cooperação","contraditório substancial","não surpresa","isonomia","duração razoável","publicidade","fundamentação","ordem cronológica","fontes","interpretação","aplicação imediata","isolamento dos atos","aplicação supletiva e subsidiária"],"theory":[["Princípios estruturantes","O CPC deve ser interpretado conforme a Constituição. Boa-fé, cooperação, paridade, contraditório efetivo, vedação à decisão-surpresa e primazia do mérito orientam todo o sistema."],["Fontes e interpretação","Lei e Constituição são centrais, mas precedentes obrigatórios, princípios, negócios processuais e técnicas de integração também influenciam a solução processual. Interpretação deve preservar coerência, efetividade e devido processo."],["Lei processual no tempo","A norma processual não retroage e se aplica imediatamente aos processos em curso, respeitando atos já praticados e situações consolidadas. O sistema adota o isolamento dos atos processuais."],["Aplicação subsidiária","Na ausência de disciplina dos processos eleitorais, trabalhistas ou administrativos, o CPC pode incidir supletiva e subsidiariamente; supletiva completa disciplina existente e subsidiária supre lacuna."],["Fontes em camadas","A Constituição condiciona validade e interpretação; a legislação disciplina o rito; precedentes qualificados vinculam nos limites legais; princípios, analogia, costumes e equidade integram ou orientam sem autorizar decisão arbitrária. Negócios processuais são fonte concreta de disciplina do procedimento entre os sujeitos."],["Direito intertemporal","A lei nova alcança os atos futuros do processo em curso, preservando atos concluídos e efeitos processuais já consolidados. Normas materiais ou híbridas exigem identificação do conteúdo protegido antes de aplicar automaticamente a regra da incidência imediata."]],"advanced":[["Contraditório não é mera ciência","Além de participação, exige possibilidade real de influência e proíbe fundamento decisório não debatido, inclusive matéria cognoscível de ofício."],["Questão intertemporal","Identifique a natureza da norma e o ato processual ainda não consumado; evite aplicar automaticamente a lei nova a efeitos já consolidados."]],"lawScheme":[{"title":"Constitucionalização","articles":"CPC, arts. 1º a 4º","checkpoints":["interpretação conforme a Constituição","inafastabilidade","inércia e impulso oficial","duração razoável e solução integral"]},{"title":"Modelo cooperativo","articles":"CPC, arts. 5º a 10","checkpoints":["boa-fé","cooperação","paridade","contraditório substancial","vedação à decisão-surpresa"]},{"title":"Publicidade, motivação e ordem","articles":"CPC, arts. 11 e 12","checkpoints":["publicidade como regra","fundamentação","ordem cronológica e exceções"]},{"title":"Eficácia e integração","articles":"CPC, arts. 13 a 15; CF, art. 5º, XXXV, LIV, LV e LXXVIII; LINDB, arts. 4º a 6º","checkpoints":["territorialidade","aplicação imediata","isolamento dos atos","incidência supletiva e subsidiária"]}],"questionGaps":["fontes do Direito Processual Civil","eficácia e interpretação da lei processual","direito processual intertemporal e normas híbridas"],"coverageNotice":"Complemente nas plataformas de questões: fontes do Direito Processual Civil; eficácia e interpretação da lei processual; direito processual intertemporal e normas híbridas. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m01","ankiDeck":"PROCESSO CIVIL::01 NORMAS FUNDAMENTAIS, FONTES E APLICAÇÃO","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc2","num":2,"title":"Jurisdição, ação, processo, pressupostos e mérito","subtitle":"CPC, arts. 16 a 41; teoria da ação e do processo","topics":["cpc-m02"],"read":"CPC, arts. 16 a 41; CF, art. 5º, XXXV; Lei 9.307/1996.","read_focus":["Diferencie jurisdição, ação, processo e procedimento.","Ação exige interesse e legitimidade; possibilidade jurídica não permanece como condição autônoma no CPC/2015.","Separe representação de substituição processual.","Estude pressupostos de existência, validade e desenvolvimento regular.","Limites da jurisdição nacional não se confundem com competência interna."],"outline":["jurisdição","características e princípios","arbitragem","ação","interesse e legitimidade","elementos da ação","classificação","cumulação","processo e procedimento","relação processual","pressupostos","objeto e mérito","questões preliminares e prejudiciais","jurisdição nacional","cooperação internacional"],"theory":[["Jurisdição e equivalentes","Jurisdição é função estatal de composição e realização do direito, marcada por substitutividade, inércia inicial e definitividade possível. Arbitragem e autocomposição são meios legítimos de solução."],["Ação e legitimidade","O direito de ação é autônomo; para postular em juízo exigem-se interesse e legitimidade. Substituição processual permite defesa, em nome próprio, de direito alheio quando autorizada."],["Processo e pressupostos","Processo é relação jurídica e método de exercício da jurisdição; procedimento é sua expressão ordenada. Pressupostos condicionam existência e validade, enquanto o mérito corresponde à pretensão submetida à decisão."],["Limites nacionais","Os arts. 21 a 25 tratam de jurisdição brasileira concorrente e exclusiva; os arts. 26 a 41 disciplinam cooperação, auxílio direto e carta rogatória."],["Espécies e procedimentos","Processo de conhecimento, execução e procedimentos de jurisdição voluntária respondem a funções distintas. O procedimento comum é subsidiário aos especiais e organiza postulação, saneamento, instrução, decisão e eventual satisfação, com adaptações permitidas pelo CPC."],["Objeto, mérito e questões","O objeto litigioso é delimitado pela pretensão e pela resistência levadas ao processo. Questão principal integra diretamente o pedido; preliminar condiciona a regularidade ou admissibilidade do exame; prejudicial condiciona logicamente a solução e pode, excepcionalmente, adquirir coisa julgada."],["Elementos e cumulação","Partes, pedido e causa de pedir individualizam a demanda e permitem testar litispendência, coisa julgada, conexão e continência. A cumulação exige competência, compatibilidade dos pedidos e adequação procedimental, admitida adaptação ao procedimento comum quando cabível."]],"advanced":[["Preliminar x prejudicial","Preliminar influencia a possibilidade ou regularidade do exame; prejudicial condiciona logicamente a decisão de outra questão."],["Arbitragem","Convenção arbitral não elimina jurisdição estatal em abstrato; distribui competência decisória e admite apoio, controle e execução judicial nos limites legais."]],"lawScheme":[{"title":"Jurisdição e ação","articles":"CPC, arts. 16 a 20","checkpoints":["jurisdição civil","interesse e legitimidade","substituição processual","ação meramente declaratória"]},{"title":"Limites nacionais","articles":"CPC, arts. 21 a 25","checkpoints":["competência internacional concorrente","competência exclusiva","litispendência estrangeira","cláusula de foro exclusivo estrangeiro"]},{"title":"Cooperação internacional","articles":"CPC, arts. 26 a 41","checkpoints":["autoridade central","auxílio direto","carta rogatória","cooperação entre órgãos jurisdicionais"]},{"title":"Arbitragem","articles":"Lei 9.307/1996, arts. 1º a 8º, 18 e 31 a 33","checkpoints":["arbitrabilidade","convenção de arbitragem","competência-competência","sentença arbitral e controle judicial"]}],"questionGaps":["espécies de processos e procedimentos","objeto do processo e mérito","questão principal, preliminar e prejudicial","concurso e cumulação de ações"],"coverageNotice":"Complemente nas plataformas de questões: espécies de processos e procedimentos; objeto do processo e mérito; questão principal, preliminar e prejudicial; concurso e cumulação de ações. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m02","ankiDeck":"PROCESSO CIVIL::02 JURISDIÇÃO, AÇÃO, PROCESSO E PRESSUPOSTOS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc3","num":3,"title":"Competência, conexão, continência e conflitos","subtitle":"CPC, arts. 42 a 69; competências originárias","topics":["cpc-m03"],"read":"CPC, arts. 42 a 69; CF, arts. 102 e 105; Lei 14.879/2024.","read_focus":["Construa uma tabela: absoluta x relativa.","Perpetuatio jurisdictionis: regra e exceções.","Conexão, continência e risco de decisões contraditórias.","Incompetência deve ser arguida em preliminar de contestação.","Leia a redação atual do art. 63 sobre eleição de foro."],"outline":["critérios de competência","funcional","material","territorial","valor","competência absoluta e relativa","perpetuação","modificação","conexão","continência","prevenção","eleição de foro","incompetência","conflito de competência","competência originária STF e STJ"],"theory":[["Critérios e natureza","Competência distribui jurisdição. Matéria, pessoa e função normalmente geram competência absoluta; território e valor, em regra, relativa, ressalvadas previsões especiais."],["Modificação","Competência relativa pode modificar-se por conexão, continência, convenção e ausência de alegação tempestiva. Absoluta não se prorroga e pode ser conhecida de ofício."],["Arguição e efeitos","A incompetência absoluta ou relativa é alegada em preliminar de contestação. A decisão preserva, em regra, efeitos dos atos até pronunciamento do juízo competente."],["Eleição de foro atual","Após a Lei 14.879/2024, a cláusula deve guardar pertinência com domicílio/residência ou local da obrigação; juízo aleatório pode justificar declinação de ofício."],["Conflito de competência x atribuições","Conflito de competência pressupõe órgãos jurisdicionais discutindo quem deve processar ou reunir causas. Conflito de atribuições envolve competências administrativas ou a fronteira entre autoridade administrativa e judicial; a solução depende da configuração constitucional, não do simples uso do nome “conflito”."],["Competência originária","A competência dos tribunais superiores decorre diretamente da Constituição e deve ser lida de forma taxativa. Identifique sujeitos, natureza do ato e órgãos em conflito antes de escolher STF ou STJ; não confunda competência originária com competência recursal."]],"advanced":[["Conflito","Pode ser positivo, negativo ou decorrer de controvérsia sobre reunião/separação; identifique o tribunal competente para solucioná-lo."],["Art. 55, §3º","Processos podem ser reunidos por risco de decisões conflitantes mesmo sem conexão técnica por pedido ou causa de pedir."]],"lawScheme":[{"title":"Critérios gerais","articles":"CPC, arts. 42 a 53","checkpoints":["perpetuatio jurisdictionis","foros gerais e especiais","competência territorial","foros de família, alimentos e reparação"]},{"title":"Modificação","articles":"CPC, arts. 54 a 63","checkpoints":["conexão","continência","risco de decisões conflitantes","prevenção","eleição de foro na redação atual"]},{"title":"Incompetência e cooperação","articles":"CPC, arts. 64 a 69","checkpoints":["preliminar de contestação","efeitos dos atos","conflito de competência","cooperação judiciária"]},{"title":"Competência originária","articles":"CF, arts. 102, I, e 105, I","checkpoints":["hipóteses originárias do STF","hipóteses originárias do STJ","conflitos entre órgãos","distinção entre competência e atribuição"]}],"questionGaps":["conflito de atribuições","competência originária dos Tribunais Superiores","critérios funcional e pelo valor em comparação sistemática"],"coverageNotice":"Complemente nas plataformas de questões: conflito de atribuições; competência originária dos Tribunais Superiores; critérios funcional e pelo valor em comparação sistemática. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m03","ankiDeck":"PROCESSO CIVIL::03 COMPETÊNCIA, CONEXÃO E CONFLITOS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc4","num":4,"title":"Partes, procuradores, responsabilidades, despesas e gratuidade","subtitle":"CPC, arts. 70 a 112","topics":["cpc-m04"],"read":"CPC, arts. 70 a 112; Lei 15.109/2025.","read_focus":["Capacidade de ser parte, processual e postulatória são planos diferentes.","Compare deveres, ato atentatório e litigância de má-fé.","Honorários sucumbenciais pertencem ao advogado.","Gratuidade pode ser parcial e não elimina responsabilidade definitiva.","Sucessão processual não se confunde com substituição processual."],"outline":["capacidade processual","curador especial","deveres","responsabilidade por dano processual","litigância de má-fé","despesas","honorários","multas","gratuidade","procuradores","mandato","sucessão das partes e procuradores","alienação da coisa litigiosa"],"theory":[["Capacidades","Capacidade de ser parte decorre da aptidão para titularizar posições; capacidade processual é exercício em juízo; capacidade postulatória pertence aos profissionais habilitados, ressalvadas exceções."],["Deveres e sanções","Todos os participantes devem agir com lealdade e cumprir decisões. Ato atentatório à dignidade da justiça e litigância de má-fé têm pressupostos, destinatários e consequências próprias."],["Despesas e honorários","Regra da causalidade e sucumbência distribui despesas e honorários. Honorários possuem natureza alimentar e regime próprio, inclusive contra a Fazenda."],["Gratuidade e atualização","A gratuidade pode abranger atos específicos e não afasta obrigação sucumbencial, apenas condiciona exigibilidade. A Lei 15.109/2025 incluiu hipótese de dispensa de adiantamento de custas em cobrança e execução de honorários."],["Representação, substituição e sucessão","Na representação, alguém atua em nome da própria parte; na substituição, o legitimado extraordinário defende em nome próprio direito alheio por autorização normativa; na sucessão, muda o sujeito que ocupa a posição processual. Cada fenômeno produz efeitos distintos sobre legitimidade e coisa julgada."],["Regularização processual","O CPC privilegia o saneamento da incapacidade ou irregularidade de representação antes da extinção. Procuração, atuação urgente sem mandato, renúncia, revogação e sucessão do advogado possuem requisitos e prazos próprios."]],"advanced":[["Alienação litigiosa","A alienação não altera automaticamente legitimidade; o adquirente pode suceder com consentimento da parte contrária ou intervir como assistente litisconsorcial."],["Fazenda e honorários","Percentuais escalonados, remessa necessária e execução contra ente público exigem leitura conjunta, sem aplicar regras privadas por analogia automática."]],"lawScheme":[{"title":"Capacidade e representação","articles":"CPC, arts. 70 a 76","checkpoints":["capacidade processual","incapazes e curador especial","representação de pessoas e entes","saneamento da incapacidade"]},{"title":"Deveres e responsabilidade","articles":"CPC, arts. 77 a 81","checkpoints":["deveres dos sujeitos","ato atentatório","litigância de má-fé","indenização, multa e despesas"]},{"title":"Despesas e honorários","articles":"CPC, arts. 82 a 97","checkpoints":["adiantamento","sucumbência e causalidade","honorários contra a Fazenda","multas e perícia"]},{"title":"Gratuidade e procuradores","articles":"CPC, arts. 98 a 112","checkpoints":["alcance e impugnação da gratuidade","suspensão da exigibilidade","mandato","sucessão e renúncia","alienação litigiosa"]}],"questionGaps":["representação, substituição e sucessão processual em confronto","mandato e regularização da representação","alienação da coisa litigiosa"],"coverageNotice":"Complemente nas plataformas de questões: representação, substituição e sucessão processual em confronto; mandato e regularização da representação; alienação da coisa litigiosa. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m04","ankiDeck":"PROCESSO CIVIL::04 PARTES, PROCURADORES, DESPESAS E GRATUIDADE","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc5","num":5,"title":"Litisconsórcio e intervenção de terceiros","subtitle":"CPC, arts. 113 a 138","topics":["cpc-m05"],"read":"CPC, arts. 113 a 138.","read_focus":["Classifique o litisconsórcio por posição, momento, obrigatoriedade e regime decisório.","Necessário não significa automaticamente unitário.","Assistência simples x litisconsorcial.","Denunciação e chamamento têm hipóteses diferentes.","IDPJ e amicus curiae possuem finalidades próprias."],"outline":["litisconsórcio ativo e passivo","inicial e ulterior","facultativo e necessário","simples e unitário","limitação","assistência","denunciação da lide","chamamento ao processo","incidente de desconsideração","amicus curiae"],"theory":[["Litisconsórcio","Pluralidade de partes pode decorrer de comunhão, conexão ou afinidade. A obrigatoriedade vem da lei ou da natureza da relação; o regime unitário depende da necessidade de decisão uniforme."],["Assistência","Terceiro com interesse jurídico ingressa para auxiliar uma parte. Na assistência litisconsorcial, a relação do assistente com o adversário justifica posição mais intensa."],["Denunciação e chamamento","Denunciação veicula direito regressivo nas hipóteses legais; chamamento amplia polo passivo para coobrigados previstos. Não confunda com correção de legitimidade."],["IDPJ e amicus","O incidente assegura contraditório antes da desconsideração, inclusive inversa. Amicus contribui com representatividade e conhecimento, sem virar parte comum."],["Mapa classificatório","Litisconsórcio ativo ou passivo indica o polo; inicial ou ulterior, o momento; facultativo ou necessário, a obrigatoriedade; simples ou unitário, a possibilidade de decisões diferentes. Necessário e unitário não são sinônimos."],["Efeitos da intervenção","Assistente, denunciado, chamado, atingido pelo IDPJ e amicus não recebem o mesmo conjunto de poderes. Para cada modalidade, memorize pressuposto de ingresso, posição ocupada, pretensão discutida, recursos admitidos e extensão dos efeitos decisórios."]],"advanced":[["Intervenção e coisa julgada","Cada modalidade produz extensão distinta de poderes, ônus e eficácia; a FCC explora generalizações indevidas."],["Denunciação sucessiva","O CPC limita a denunciação sucessiva a uma única, deixando pretensões posteriores para ação autônoma."]],"lawScheme":[{"title":"Litisconsórcio","articles":"CPC, arts. 113 a 118","checkpoints":["facultativo e necessário","simples e unitário","limitação do multitudinário","autonomia dos litisconsortes"]},{"title":"Assistência","articles":"CPC, arts. 119 a 124","checkpoints":["interesse jurídico","assistência simples","assistência litisconsorcial","efeito da justiça da decisão"]},{"title":"Denunciação e chamamento","articles":"CPC, arts. 125 a 132","checkpoints":["direito regressivo","uma denunciação sucessiva","coobrigados chamados","efeitos da sentença"]},{"title":"IDPJ e amicus curiae","articles":"CPC, arts. 133 a 138","checkpoints":["desconsideração direta e inversa","suspensão e contraditório","representatividade adequada","poderes e recursos do amicus"]}],"questionGaps":["efeitos de cada modalidade de intervenção sobre poderes e coisa julgada","denunciação sucessiva","limitação do litisconsórcio multitudinário"],"coverageNotice":"Complemente nas plataformas de questões: efeitos de cada modalidade de intervenção sobre poderes e coisa julgada; denunciação sucessiva; limitação do litisconsórcio multitudinário. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m05","ankiDeck":"PROCESSO CIVIL::05 LITISCONSÓRCIO E INTERVENÇÃO DE TERCEIROS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc6","num":6,"title":"Juiz, auxiliares, Ministério Público, Advocacia e Defensoria","subtitle":"CPC, arts. 139 a 149, 156 a 158, 162 a 164 e 176 a 187; Fazenda Pública em juízo","topics":["cpc-m06"],"read":"CPC, arts. 139 a 149, 156 a 158, 162 a 164 e 176 a 187; CPC, arts. 85, §§ 3º a 7º, 183, 496, 534, 535 e 910; CF, art. 100.","read_focus":["Poderes do juiz devem respeitar contraditório e fundamentação.","Impedimento é objetivo; suspeição, subjetiva.","Perito, intérprete e tradutor possuem atribuições, deveres, impedimentos e regimes próprios.","MP como parte x fiscal da ordem jurídica.","Prazos e intimações da Advocacia Pública e Defensoria.","Sistematize prerrogativas da Fazenda Pública."],"outline":["poderes e deveres do juiz","responsabilidade","impedimento","suspeição","auxiliares","perito","intérprete e tradutor","Ministério Público","Advocacia Pública","Defensoria Pública","Fazenda Pública","prazos em dobro","intimação pessoal"],"theory":[["Direção do processo","O juiz deve assegurar duração razoável, igualdade, adequação e efetividade, podendo adotar medidas executivas necessárias, sempre com proporcionalidade, contraditório e motivação."],["Imparcialidade","Impedimento decorre de situações objetivas e tem regime mais rígido; suspeição se relaciona a vínculos subjetivos. Ambas alcançam auxiliares nos limites legais."],["Funções essenciais","MP atua como parte ou fiscal; Advocacia Pública representa entes; Defensoria presta assistência integral. Cada instituição possui intimação pessoal e prazos conforme o CPC."],["Fazenda Pública","Prazos diferenciados, remessa necessária, honorários escalonados, execução por precatório/RPV e restrições materiais formam sistema, não privilégio isolado."],["Auxiliares em espécie","No recorte do edital, concentre-se no perito, que fornece conhecimento técnico e deve ser imparcial, e no intérprete e tradutor, que viabilizam a compreensão linguística e comunicacional. Nomeação, impedimento, substituição, remuneração e responsabilidade seguem as regras específicas do CPC."],["Prerrogativas da Fazenda","A Fazenda possui intimação pessoal e prazo em dobro quando a lei não fixa prazo próprio, além de regimes específicos de honorários, remessa necessária, cumprimento e execução. A existência de uma prerrogativa não autoriza estender automaticamente todas as demais."]],"advanced":[["Poder geral de efetivação","O art. 139, IV, não autoriza medida atípica automática; exige utilidade, necessidade, proporcionalidade e fundamentação concreta."],["Curador especial","A Defensoria exerce curadoria nas hipóteses legais; curadoria não pressupõe defesa de mérito favorável, mas garantia de contraditório."]],"lawScheme":[{"title":"Juiz","articles":"CPC, arts. 139 a 143","checkpoints":["direção e efetivação","dilação e adequação","responsabilidade","vedação ao non liquet"]},{"title":"Imparcialidade","articles":"CPC, arts. 144 a 148","checkpoints":["impedimento","suspeição","procedimento de arguição","extensão a auxiliares e demais sujeitos"]},{"title":"Auxiliares expressamente previstos","articles":"CPC, art. 149; arts. 156 a 158 e 162 a 164","checkpoints":["classificação geral dos auxiliares","perito: nomeação, impedimento e substituição","intérprete e tradutor","deveres, remuneração e responsabilidade"]},{"title":"Funções essenciais e Fazenda","articles":"CPC, arts. 176 a 187; arts. 85, §§ 3º a 7º, 183, 496, 534, 535 e 910; CF, art. 100","checkpoints":["MP como parte ou fiscal","Advocacia Pública","Defensoria Pública","prazos e intimação pessoal","remessa, honorários e pagamento público"]}],"questionGaps":["perito","intérprete e tradutor","prerrogativas da Fazenda Pública tratadas como sistema"],"coverageNotice":"Complemente nas plataformas de questões: perito; intérprete e tradutor; prerrogativas da Fazenda Pública tratadas como sistema. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m06","ankiDeck":"PROCESSO CIVIL::06 JUIZ, AUXILIARES, MP, ADVOCACIA E DEFENSORIA","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc7","num":7,"title":"Atos processuais, negócios, tempo, lugar e prazos","subtitle":"CPC, arts. 188 a 235","topics":["cpc-m07"],"read":"CPC, arts. 188 a 235; Lei 11.419/2006.","read_focus":["Instrumentalidade das formas: finalidade e ausência de prejuízo.","Negócio processual e calendário exigem requisitos.","Prazos processuais em dias úteis.","Diferencie prazo próprio, impróprio, legal e judicial.","Suspensão de 20 de dezembro a 20 de janeiro."],"outline":["forma","publicidade e segredo","negócio processual","calendário","processo eletrônico","pronunciamentos","atos do escrivão","tempo e lugar","prazos","dias úteis","justa causa","renúncia","suspensão","recesso"],"theory":[["Forma e validade","Atos independem de forma determinada salvo exigência legal; alcançada a finalidade sem prejuízo, preserva-se o ato. Publicidade é regra e segredo, exceção legal."],["Negócios e calendário","Partes plenamente capazes podem estipular mudanças procedimentais em direitos autocomponíveis, sob controle judicial de validade. Calendário dispensa intimação dos atos fixados."],["Tempo e prazos","Prazos processuais contam-se em dias úteis; exclui-se o começo e inclui-se o vencimento, observadas disponibilidade eletrônica, suspensão e prorrogações."],["Processo eletrônico","Atos eletrônicos obedecem CPC e Lei 11.419. A Lei 15.479/2026 prevê nova disciplina de dados e alimentos, mas entra em vigor apenas em 30/07/2027."],["Pronunciamentos e atos","Sentença se identifica pelo conteúdo dos arts. 485 ou 487 e pelo encerramento da fase cognitiva ou execução; decisão interlocutória resolve questão sem esse encerramento; despacho apenas impulsiona. A denominação dada pelo juiz não prevalece sobre conteúdo e efeito."],["Prazos e preclusão","Prazo legal vem da lei, judicial é fixado pelo juiz e convencional decorre de negócio válido. A perda da faculdade por tempo gera preclusão temporal; justa causa pode autorizar restituição. Prazos do juiz e auxiliares são, em regra, impróprios e não produzem a mesma consequência da perda da faculdade da parte."]],"advanced":[["Prazo material x processual","Dias úteis valem para prazo processual; decadência e prescrição material não recebem a regra automaticamente."],["Intempestividade","Justa causa pode permitir prática posterior; indisponibilidade do sistema e feriado local possuem prova e regimes específicos."]],"lawScheme":[{"title":"Forma e negócios","articles":"CPC, arts. 188 a 202","checkpoints":["instrumentalidade","publicidade e segredo","negócio processual","calendário","idioma e documentação"]},{"title":"Prática eletrônica e pronunciamentos","articles":"CPC, arts. 193 a 211; Lei 11.419/2006, arts. 1º a 12","checkpoints":["assinatura e disponibilidade","sentença, decisão e despacho","acórdão","atos de secretaria"]},{"title":"Tempo e lugar","articles":"CPC, arts. 212 a 217","checkpoints":["horário","férias e feriados","atos fora da sede","atos urgentes"]},{"title":"Prazos","articles":"CPC, arts. 218 a 235","checkpoints":["dias úteis","termo inicial e final","suspensão","justa causa","renúncia","prazos diferenciados"]}],"questionGaps":["negócios processuais e calendário","processo eletrônico","pronunciamentos judiciais e atos do escrivão","prazos impróprios e justa causa"],"coverageNotice":"Complemente nas plataformas de questões: negócios processuais e calendário; processo eletrônico; pronunciamentos judiciais e atos do escrivão; prazos impróprios e justa causa. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m07","ankiDeck":"PROCESSO CIVIL::07 ATOS PROCESSUAIS, NEGÓCIOS E PRAZOS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc8","num":8,"title":"Comunicação dos atos processuais e nulidades","subtitle":"CPC, arts. 236 a 283","topics":["cpc-m08"],"read":"CPC, arts. 236 a 283.","read_focus":["Citação válida integra o réu e produz efeitos legais.","Compare citação eletrônica, postal, oficial e edital.","Cartas: ordem, rogatória, precatória e arbitral.","Nulidade exige prejuízo e deve ser arguida oportunamente."],"outline":["citação","comparecimento espontâneo","citação eletrônica","correio","oficial","hora certa","edital","cartas","intimações","nulidades","prejuízo"],"theory":[["Citação","É ato de convocação para integrar relação processual. Falta ou nulidade pode ser suprida pelo comparecimento espontâneo, que inicia prazo de defesa."],["Modalidades","A preferência legal e os requisitos variam entre eletrônica, correio, oficial, hora certa e edital. Pessoa jurídica deve manter dados atualizados para comunicação eletrônica."],["Nulidades","Não há nulidade sem prejuízo. A parte deve alegá-la na primeira oportunidade, salvo matéria cognoscível de ofício, e não pode beneficiar-se de vício que causou."],["Comunicação em sequência","Primeiro identifique o destinatário e a finalidade: citação integra o demandado; intimação dá ciência de ato ou termo; carta permite prática por outro órgão. Depois escolha a modalidade e confira requisitos, preferência legal e eventual excepcionalidade."]],"advanced":[["Efeitos da citação","Constituição em mora e interrupção prescricional devem ser lidas com o Código Civil e a retroação prevista no CPC."],["Edital","É modalidade excepcional; seu uso prematuro compromete contraditório e pode gerar nulidade mesmo após trânsito, conforme o caso."]],"lawScheme":[{"title":"Comunicação e cartas","articles":"CPC, arts. 236 a 263","checkpoints":["atos de comunicação","cartas de ordem, rogatória, precatória e arbitral","requisitos e cumprimento","cooperação"]},{"title":"Citação","articles":"CPC, arts. 238 a 259","checkpoints":["efeitos","comparecimento espontâneo","eletrônica, correio e oficial","hora certa","edital"]},{"title":"Intimações e nulidades","articles":"CPC, arts. 269 a 283","checkpoints":["formas de intimação","publicação","primeira oportunidade","prejuízo","aproveitamento dos atos"]}],"questionGaps":["cartas em suas modalidades","citação eletrônica, postal, por oficial, hora certa e edital","intimações e nulidades"],"coverageNotice":"Complemente nas plataformas de questões: cartas em suas modalidades; citação eletrônica, postal, por oficial, hora certa e edital; intimações e nulidades. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m08","ankiDeck":"PROCESSO CIVIL::08 COMUNICAÇÃO DOS ATOS E NULIDADES","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc9","num":9,"title":"Tutela provisória de urgência e de evidência","subtitle":"CPC, arts. 294 a 311","topics":["cpc-m09"],"read":"CPC, arts. 294 a 311.","read_focus":["Urgência = probabilidade + perigo.","Cautelar conserva; antecipada satisfaz.","Antecedente x incidental.","Estabilização somente na antecipada antecedente.","Tutela da evidência dispensa perigo, mas exige hipótese legal."],"outline":["tutela provisória","urgência","cautelar","antecipada","antecedente","incidental","caução","responsabilidade","estabilização","tutela de evidência","fungibilidade"],"theory":[["Estrutura","Tutela provisória funda-se em urgência ou evidência. Urgência pode ser cautelar ou antecipada e ser requerida de modo antecedente ou incidental."],["Requisitos e reversibilidade","Probabilidade do direito e perigo de dano ou risco ao resultado útil são requisitos comuns. Tutela antecipada não deve ser concedida quando houver perigo de irreversibilidade dos efeitos."],["Estabilização","A tutela antecipada antecedente pode estabilizar-se se não impugnada pelo recurso pertinente; o processo é extinto e cabe ação revisional no prazo legal."],["Evidência","Dispensa perigo, mas depende das hipóteses taxativas do art. 311; liminar sem ouvir a outra parte só nos incisos autorizados pelo art. 9º."],["Cautelar, antecipada e fungibilidade","Tutela cautelar conserva a utilidade do resultado; antecipada satisfaz provisoriamente. O juiz pode adequar a técnica à natureza do pedido, respeitando contraditório e oportunidade de adaptação, sem transformar erro grosseiro em surpresa processual."],["Evidência por hipótese","O perigo é dispensado, mas cada inciso do art. 311 exige suporte próprio: abuso defensivo, prova documental ligada a precedente vinculante, depósito documentalmente comprovado ou prova documental suficiente sem contraprova capaz de gerar dúvida razoável."]],"advanced":[["Cognição provisória","Decisão pode ser revogada ou modificada, mas exige fundamentação clara, inclusive para negar a medida."],["Cautelar antecedente","Efetivada a cautelar, o pedido principal deve ser formulado no prazo legal; não se confunde com estabilização da antecipada."]],"lawScheme":[{"title":"Disposições comuns","articles":"CPC, arts. 294 a 299","checkpoints":["urgência ou evidência","antecedente ou incidental","competência","efetivação e motivação"]},{"title":"Urgência","articles":"CPC, arts. 300 a 302","checkpoints":["probabilidade e perigo","caução","irreversibilidade","responsabilidade objetiva nas hipóteses legais"]},{"title":"Antecipada antecedente","articles":"CPC, arts. 303 e 304","checkpoints":["aditamento","estabilização","extinção","ação revisional em dois anos"]},{"title":"Cautelar e evidência","articles":"CPC, arts. 305 a 311","checkpoints":["pedido cautelar antecedente","formulação do pedido principal","cessação da eficácia","hipóteses taxativas de evidência"]}],"questionGaps":["fungibilidade entre tutelas","responsabilidade pela efetivação da tutela","diferenças internas da tutela de evidência"],"coverageNotice":"Complemente nas plataformas de questões: fungibilidade entre tutelas; responsabilidade pela efetivação da tutela; diferenças internas da tutela de evidência. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m09","ankiDeck":"PROCESSO CIVIL::09 TUTELA PROVISÓRIA","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc10","num":10,"title":"Formação, suspensão, extinção e petição inicial","subtitle":"CPC, arts. 312 a 334","topics":["cpc-m10"],"read":"CPC, arts. 312 a 334.","read_focus":["Propositura ocorre com protocolo; efeitos ao réu dependem de citação válida.","Suspensão tem causas e limites.","Primazia do mérito exige oportunidade de correção.","Petição inicial: requisitos, documentos e pedido.","Indeferimento x improcedência liminar.","Audiência de conciliação e mediação."],"outline":["formação","suspensão","extinção","emenda","petição inicial","requisitos","documentos","pedido","cumulação","alternativo e subsidiário","indeferimento","improcedência liminar","audiência de conciliação"],"theory":[["Formação e suspensão","A ação considera-se proposta com o protocolo; suspensão decorre das causas legais e paralisa atos, salvo urgentes. Extinção deve respeitar primazia do julgamento de mérito."],["Petição inicial","Deve identificar juízo, partes, fatos, fundamentos, pedido, valor, provas e opção sobre audiência, com documentos indispensáveis. Defeito sanável exige emenda específica."],["Pedido","Deve ser certo e determinado, ressalvadas hipóteses legais. Cumulação exige compatibilidade, competência e adequação procedimental; pedidos alternativo, subsidiário e sucessivo têm lógicas distintas."],["Indeferimento e improcedência liminar","Indeferimento normalmente resolve vício da demanda sem mérito; improcedência liminar decide mérito antes da citação nas hipóteses estritas do art. 332."],["Fases do procedimento comum","A postulação delimita demanda e defesa; a fase organizatória corrige vícios e fixa questões; a instrução produz prova; a decisão resolve o que foi delimitado. Nem todo processo percorre todas as fases, pois pode haver extinção ou julgamento antecipado."],["Suspensão, extinção e primazia do mérito","Suspensão paralisa temporariamente atos, ressalvados os urgentes; extinção encerra a etapa processual mediante pronunciamento. Antes de extinguir sem mérito por vício sanável, o juiz deve oportunizar correção, concretizando a primazia da decisão de mérito."],["Pedido","Pedido imediato é a providência jurisdicional e mediato é o bem da vida. Regra de certeza e determinação convive com pedidos genéricos legalmente admitidos; cumulação, alternância, subsidiariedade e prestações sucessivas têm disciplina própria."]],"advanced":[["Negócio e cumulação","Diferença de procedimentos pode ser superada pelo procedimento comum se técnicas especiais forem compatíveis."],["Audiência inicial","Dispensa exige manifestação de todos quando a autocomposição for possível; direitos indisponíveis podem admitir autocomposição em determinados efeitos."]],"lawScheme":[{"title":"Formação, suspensão e extinção","articles":"CPC, arts. 312 a 317","checkpoints":["propositura e efeitos ao réu","hipóteses de suspensão","questão prejudicial externa","extinção e chance de correção"]},{"title":"Procedimento comum","articles":"CPC, art. 318","checkpoints":["regra residual","aplicação subsidiária aos especiais","fases postulatória, organizatória, instrutória e decisória"]},{"title":"Petição e pedido","articles":"CPC, arts. 319 a 329","checkpoints":["requisitos","documentos indispensáveis","emenda","pedido determinado e exceções","cumulação e alteração"]},{"title":"Juízo inicial","articles":"CPC, arts. 330 a 334","checkpoints":["indeferimento","apelação e retratação","improcedência liminar","audiência de conciliação ou mediação"]}],"questionGaps":["fases e aspectos gerais do procedimento comum","suspensão e extinção do processo","pedido e suas alterações"],"coverageNotice":"Complemente nas plataformas de questões: fases e aspectos gerais do procedimento comum; suspensão e extinção do processo; pedido e suas alterações. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m10","ankiDeck":"PROCESSO CIVIL::10 FORMAÇÃO, SUSPENSÃO E PETIÇÃO INICIAL","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc11","num":11,"title":"Defesa, revelia, saneamento e julgamento conforme o estado","subtitle":"CPC, arts. 335 a 368","topics":["cpc-m11"],"read":"CPC, arts. 335 a 368.","read_focus":["Contestação concentra toda matéria defensiva.","Reconvenção pode ampliar sujeitos e é apresentada na contestação.","Revelia não produz automaticamente procedência.","Providências preliminares antecedem saneamento.","Julgamento antecipado total x parcial.","Audiência de instrução e ordem dos atos."],"outline":["contestação","ônus da impugnação específica","preliminares","reconvenção","revelia","providências preliminares","saneamento","julgamento antecipado","julgamento parcial","audiência de instrução"],"theory":[["Contestação","O réu deve concentrar defesa processual e de mérito, impugnar especificamente os fatos e alegar preliminares do art. 337. Matéria superveniente e cognoscível de ofício admitem tratamento posterior."],["Reconvenção e revelia","Reconvenção veicula pretensão conexa e admite ampliação subjetiva legal. Revelia produz efeitos de fato apenas quando presentes pressupostos e não impede intervenção posterior do revel."],["Saneamento","O juiz resolve questões pendentes, delimita fatos e direito, distribui ônus da prova e organiza instrução. Partes podem pedir esclarecimentos e construir saneamento consensual."],["Julgamento conforme o estado","Extinção, julgamento antecipado total e parcial possuem pressupostos diferentes. A decisão parcial de mérito é impugnável por agravo de instrumento."],["Providências preliminares","Depois da defesa, o juiz verifica fatos impeditivos, modificativos ou extintivos, preliminares e documentos, abrindo contraditório ao autor quando necessário. Também determina correção de irregularidades antes de definir a próxima técnica decisória."],["Julgamento conforme o estado","O processo pode ser extinto, julgado integralmente quando prova adicional é desnecessária, ou parcialmente quando parcela do mérito é incontroversa ou imediatamente decidível. O julgamento parcial é decisão interlocutória de mérito e admite liquidação ou cumprimento."],["Saneamento","A decisão saneadora estabiliza as questões controvertidas, define provas e distribui ônus. As partes podem pedir esclarecimentos em prazo comum e, em causa complexa, participar de audiência de saneamento cooperativo."]],"advanced":[["Ônus de impugnação","Não alcança fatos cuja confissão não seja admissível, petição sem instrumento indispensável ou alegações incompatíveis com defesa considerada em conjunto."],["Saneamento compartilhado","Em causa complexa, audiência pode ser designada para organização cooperativa e estabilização dos pontos controvertidos."]],"lawScheme":[{"title":"Contestação","articles":"CPC, arts. 335 a 342","checkpoints":["termo inicial","concentração","preliminares","impugnação específica","alegações posteriores"]},{"title":"Reconvenção e revelia","articles":"CPC, arts. 343 a 346","checkpoints":["conexão","ampliação subjetiva","efeitos da revelia","exceções","intervenção tardia do revel"]},{"title":"Providências e julgamento","articles":"CPC, arts. 347 a 356","checkpoints":["réplica","correção de vícios","extinção","julgamento antecipado total e parcial"]},{"title":"Saneamento e audiência","articles":"CPC, arts. 357 a 368","checkpoints":["delimitação de fatos e direito","ônus da prova","saneamento consensual e compartilhado","ordem da instrução","debates"]}],"questionGaps":["providências preliminares","saneamento e organização do processo","julgamento conforme o estado do processo"],"coverageNotice":"Complemente nas plataformas de questões: providências preliminares; saneamento e organização do processo; julgamento conforme o estado do processo. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m11","ankiDeck":"PROCESSO CIVIL::11 DEFESA, REVELIA, SANEAMENTO E JULGAMENTO","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc12","num":12,"title":"Provas: teoria geral e meios em espécie","subtitle":"CPC, arts. 369 a 484","topics":["cpc-m12"],"read":"CPC, arts. 369 a 484.","read_focus":["Prova pertence ao processo, não à parte que a produziu.","Ônus estático e distribuição dinâmica.","Convenção probatória tem limites.","Produção antecipada não exige urgência em todas as hipóteses.","Compare depoimento, confissão, exibição, documentos, testemunha, perícia e inspeção."],"outline":["direito à prova","poder instrutório","prova emprestada","ônus","distribuição dinâmica","fatos sem prova","produção antecipada","ata notarial","depoimento","confissão","exibição","documentos","prova eletrônica","testemunha","perícia","inspeção"],"theory":[["Teoria geral","Partes podem usar meios legais e moralmente legítimos; o juiz determina provas necessárias e indefere diligências inúteis, motivadamente. Prova emprestada exige contraditório."],["Ônus","Autor prova fato constitutivo e réu, impeditivo, modificativo ou extintivo. Distribuição dinâmica exige decisão fundamentada e oportunidade efetiva de cumprimento."],["Antecipação e prova documental","Produção antecipada serve para risco de perda, viabilizar autocomposição ou avaliar ajuizamento. Ata notarial e documento eletrônico integram o sistema documental."],["Meios pessoais e técnicos","Depoimento e confissão não se confundem; testemunhas têm impedimentos; perícia pode ser simplificada; inspeção permite percepção direta do objeto pelo juiz."],["Exibição e documentos eletrônicos","A exibição pode recair sobre parte ou terceiro, com procedimentos e consequências distintos. Documento eletrônico é admitido quando autenticidade e integridade possam ser verificadas, e sua força não depende automaticamente de conversão em papel."],["Produção antecipada sem urgência","Além do risco de perecimento, a prova pode ser antecipada para viabilizar autocomposição ou permitir avaliar se a ação deve ser proposta. O juízo da antecipação não decide o mérito nem fixa previamente as consequências jurídicas dos fatos."],["Valoração e inspeção","O juiz aprecia racionalmente o conjunto probatório e deve explicar por que determinado elemento convence. A inspeção permite contato direto com pessoa ou coisa; a raridade prática não reduz sua presença expressa no edital."]],"advanced":[["Convenção sobre ônus","É admitida antes ou durante o processo, salvo direito indisponível ou dificuldade excessiva para uma parte."],["Valoração","O CPC adota persuasão racional: o juiz aprecia o conjunto e explica as razões, sem tarifa abstrata, ressalvadas regras legais específicas."]],"lawScheme":[{"title":"Teoria geral","articles":"CPC, arts. 369 a 380","checkpoints":["meios lícitos e moralmente legítimos","poder instrutório","prova emprestada","ônus estático e dinâmico","fatos dispensados"]},{"title":"Produção antecipada e ata","articles":"CPC, arts. 381 a 384","checkpoints":["três hipóteses de antecipação","competência","ausência de valoração","documentação notarial de fatos"]},{"title":"Prova oral e exibição","articles":"CPC, arts. 385 a 404","checkpoints":["depoimento","confissão","exibição pela parte ou terceiro","recusa e consequências"]},{"title":"Documentos, testemunhas, perícia e inspeção","articles":"CPC, arts. 405 a 484","checkpoints":["força e arguição documental","documento eletrônico","admissibilidade testemunhal","perícia e simplificada","inspeção direta"]}],"questionGaps":["exibição de documento ou coisa","ata notarial","inspeção judicial","documentos eletrônicos"],"coverageNotice":"Complemente nas plataformas de questões: exibição de documento ou coisa; ata notarial; inspeção judicial; documentos eletrônicos. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m12","ankiDeck":"PROCESSO CIVIL::12 PROVAS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc13","num":13,"title":"Sentença, remessa necessária, coisa julgada e liquidação","subtitle":"CPC, arts. 485 a 512","topics":["cpc-m13"],"read":"CPC, arts. 485 a 512.","read_focus":["Sentença sem mérito x com mérito.","Elementos e fundamentação analítica.","Congruência: pedido e causa de pedir.","Tutela específica de fazer, não fazer e entregar.","Remessa necessária tem hipóteses e dispensas.","Coisa julgada: limites objetivos e subjetivos.","Liquidação não rediscute mérito."],"outline":["sentença","extinção sem mérito","resolução de mérito","elementos","fundamentação","congruência","fato superveniente","tutela específica","remessa necessária","coisa julgada","questão prejudicial","limites","liquidação por arbitramento","procedimento comum"],"theory":[["Sentença e mérito","Art. 485 reúne hipóteses sem resolução; art. 487, com resolução. Antes de extinguir sem mérito, o juiz deve permitir correção quando possível."],["Fundamentação e congruência","Decisão deve enfrentar argumentos capazes de alterar a conclusão e observar limites do pedido, sem decisão extra, ultra ou citra petita."],["Coisa julgada","A autoridade recai sobre decisão de mérito não mais impugnável; motivos não fazem coisa julgada, mas questão prejudicial pode fazê-lo se presentes requisitos do art. 503."],["Liquidação","Apura o quantum por arbitramento ou procedimento comum, conforme necessidade. É vedado modificar sentença ou rediscutir lide."],["Conceito, classificação e efeitos","Sentença é definida por conteúdo e função processual. Pode ser terminativa ou definitiva, declaratória, constitutiva ou condenatória, e produzir efeitos principais, reflexos e anexos. Publicação torna o pronunciamento acessível e limita sua alteração às hipóteses legais."],["Tutela específica","Nas obrigações de fazer, não fazer e entregar coisa, a prioridade é obter resultado prático equivalente ao adimplemento, mediante medidas indutivas, mandamentais ou sub-rogatórias. Perdas e danos não são conversão automática quando a prestação específica ainda é possível e útil."],["Remessa necessária","A remessa é condição legal de eficácia de determinadas sentenças contra entes públicos, não recurso. Verifique ente, valor, liquidez e fundamento em precedentes antes de concluir pela incidência ou dispensa."]],"advanced":[["Remessa necessária","Não é recurso; impede eficácia plena da sentença contra entes públicos nas hipóteses legais, com limites de valor e exceções por precedentes."],["Capítulos decisórios","Trânsito, nulidade e cumprimento podem ser analisados por capítulos autônomos; a FCC explora coisa julgada parcial."]],"lawScheme":[{"title":"Extinção e mérito","articles":"CPC, arts. 485 a 488","checkpoints":["hipóteses sem mérito","resolução de mérito","retratação","preferência pela solução meritória favorável"]},{"title":"Sentença","articles":"CPC, arts. 489 a 495","checkpoints":["elementos","fundamentação analítica","congruência","fato superveniente","publicação e hipoteca judiciária"]},{"title":"Remessa e tutela específica","articles":"CPC, arts. 496 a 501","checkpoints":["entes e limites","dispensas","fazer, não fazer e entregar","medidas de efetivação"]},{"title":"Coisa julgada e liquidação","articles":"CPC, arts. 502 a 512","checkpoints":["formal e material","questão prejudicial","limites objetivos e subjetivos","arbitramento e procedimento comum"]}],"questionGaps":["classificações, efeitos e publicação da sentença","tutela específica de fazer, não fazer e entregar coisa","remessa necessária em confronto com recurso"],"coverageNotice":"Complemente nas plataformas de questões: classificações, efeitos e publicação da sentença; tutela específica de fazer, não fazer e entregar coisa; remessa necessária em confronto com recurso. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m13","ankiDeck":"PROCESSO CIVIL::13 SENTENÇA, REMESSA, COISA JULGADA E LIQUIDAÇÃO","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc14","num":14,"title":"Cumprimento de sentença e meios de impugnação","subtitle":"CPC, arts. 513 a 538","topics":["cpc-m14"],"read":"CPC, arts. 513 a 538; Lei 15.479/2026 com vigência futura.","read_focus":["Cumprimento provisório x definitivo.","Intimação para pagar e multa/honorários.","Impugnação: matérias e efeito.","Obrigações de fazer, não fazer, entregar e alimentos.","Fazenda Pública tem rito próprio.","Atenção: art. 529-A só entrará em vigor em 30/07/2027."],"outline":["regras gerais","cumprimento provisório","pagar quantia","multa e honorários","impugnação","inexigibilidade","Fazenda Pública","precatório e RPV","alimentos","prisão civil","desconto","fazer e não fazer","entregar coisa"],"theory":[["Estrutura e intimação","Cumprimento ocorre perante juízo competente e exige requerimento nas obrigações pecuniárias. Forma de intimação varia conforme representação e situação do devedor."],["Quantia e impugnação","Não pago em quinze dias, incidem multa e honorários. Impugnação não suspende automaticamente e admite matérias taxativas, inclusive inexigibilidade e excesso."],["Obrigações especiais","Alimentos, Fazenda, fazer, não fazer e entregar coisa recebem técnicas próprias, como prisão, desconto, multa coercitiva e requisição de pagamento."],["Mudança futura","A Lei 15.479/2026 criou transferência automática mensal de alimentos e ajustes eletrônicos, mas sua vigência começa um ano após a publicação; até lá, não trate o art. 529-A como vigente."],["Meios de impugnação","A impugnação ao cumprimento é defesa incidental com matérias legalmente delimitadas e, em regra, sem suspensão automática. Erro de cálculo, inexigibilidade, ilegitimidade, excesso e fatos supervenientes exigem alegação e prova adequadas; decisões proferidas no cumprimento podem admitir o recurso pertinente."],["Ritos especiais","Alimentos combinam coerção pessoal, desconto e expropriação conforme a parcela; Fazenda Pública não paga pelo rito comum de quinze dias, mas por precatório ou RPV após sua oportunidade de impugnação; fazer, não fazer e entregar privilegiam resultado específico."],["Vigência futura","A transferência automática mensal prevista na Lei 15.479/2026 ainda não integra o direito vigente em 18/08/2026: a entrada em vigor ocorrerá em 30/07/2027. O material separa regra atual de mudança futura."]],"advanced":[["Título inconstitucional","Inexigibilidade por decisão do STF depende do momento do pronunciamento e pode exigir ação rescisória quando posterior ao trânsito."],["Cumprimento provisório","Corre por responsabilidade do exequente e pode alcançar atos expropriatórios mediante caução, ressalvadas dispensas legais."]],"lawScheme":[{"title":"Regras gerais","articles":"CPC, arts. 513 a 519","checkpoints":["competência","requerimento","intimação do devedor","protesto e cadastro","decisões transitadas parcialmente"]},{"title":"Provisório e quantia","articles":"CPC, arts. 520 a 527","checkpoints":["responsabilidade e caução","quinze dias","multa e honorários","impugnação e efeito suspensivo"]},{"title":"Alimentos","articles":"CPC, arts. 528 a 533","checkpoints":["prisão civil","expropriação","desconto","parcelas que autorizam coerção","constituição de capital"]},{"title":"Fazenda e tutela específica","articles":"CPC, arts. 534 a 538; CF, art. 100","checkpoints":["demonstrativo","impugnação pública","precatório e RPV","medidas de fazer e não fazer","entrega de coisa"]}],"questionGaps":["cumprimento contra a Fazenda Pública","cumprimento de alimentos","deveres de fazer, não fazer e entregar coisa em comparação"],"coverageNotice":"Complemente nas plataformas de questões: cumprimento contra a Fazenda Pública; cumprimento de alimentos; deveres de fazer, não fazer e entregar coisa em comparação. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m14","ankiDeck":"PROCESSO CIVIL::14 CUMPRIMENTO DE SENTENÇA","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc15","num":15,"title":"Recursos, precedentes, repercussão e repetitivos","subtitle":"CPC, arts. 926 a 1.044; CF, art. 103-A","topics":["cpc-m15"],"read":"CPC, arts. 926 a 965 e 994 a 1.044; CF, arts. 102, §3º, 103-A e 105, §§2º e 3º; Lei 14.939/2024; Lei 15.484/2026.","read_focus":["Princípios recursais, admissibilidade e efeitos.","Agravo interno x instrumento.","Embargos de declaração interrompem prazo.","Precedentes do art. 927 e fundamentação.","Repercussão geral e recursos repetitivos.","Lei 15.484/2026 entra em vigor em 03/09/2026."],"outline":["teoria geral dos recursos","juízo de admissibilidade","efeitos","agravo interno","agravo de instrumento","embargos de declaração","precedentes","súmula vinculante","repercussão geral","recurso extraordinário e especial","repetitivos","feriado local","relevância da questão federal"],"theory":[["Sistema recursal","Taxatividade, unirrecorribilidade, dialeticidade, voluntariedade e vedação à reforma para pior orientam recursos. Admissibilidade examina requisitos antes do mérito."],["Agravos e embargos","Agravo interno impugna decisão monocrática; instrumento cabe nas hipóteses legais e na taxatividade mitigada; embargos corrigem obscuridade, contradição, omissão ou erro material."],["Precedentes e repetitivos","Tribunais devem manter jurisprudência estável, íntegra e coerente. Distinção e superação exigem fundamentação; repetitivos racionalizam demandas múltiplas."],["Atualizações","Lei 14.939/2024 permite saneamento da prova de feriado local. Lei 15.484/2026 disciplina relevância da questão federal no REsp, mas somente a partir de 03/09/2026."],["Admissibilidade e efeitos","Tempestividade, preparo, regularidade formal, legitimidade, interesse e cabimento integram a admissibilidade. Efeito devolutivo é comum; suspensão depende de regra ou decisão. Substituição da decisão recorrida ocorre nos limites do julgamento do mérito recursal."],["Agravos","Agravo de instrumento ataca interlocutórias legalmente recorríveis de imediato, inclusive pela taxatividade mitigada quando a postergação inutiliza o exame. Agravo interno leva decisão monocrática ao colegiado e exige impugnação específica."],["Precedente não é só ementa","Aplicar precedente requer identificar fatos relevantes, razão determinante e aderência ao caso. Distinção demonstra diferença relevante; superação modifica orientação mediante fundamentação reforçada e pode ter efeitos modulados."],["Atualizações de 2024 e 2026","A Lei 14.939/2024 permite saneamento da falta de comprovação do feriado local. A relevância da questão federal no recurso especial, disciplinada pela Lei 15.484/2026, só entra em vigor em 03/09/2026."]],"advanced":[["Súmula vinculante","Aprovada por dois terços do STF após reiteradas decisões, vincula Judiciário e Administração; reclamação protege sua autoridade."],["Taxatividade mitigada","Agravo pode ser admitido fora do rol quando a postergação tornar inútil o exame futuro, conforme tese do STJ."]],"lawScheme":[{"title":"Precedentes","articles":"CPC, arts. 926 a 928 e 927, §§ 1º a 5º","checkpoints":["estabilidade, integridade e coerência","precedentes obrigatórios","contraditório e fundamentação","modulação e publicidade"]},{"title":"Disposições gerais","articles":"CPC, arts. 994 a 1.008","checkpoints":["rol de recursos","legitimidade","prazo","preparo","efeitos","recurso adesivo e fatos supervenientes"]},{"title":"Apelação","articles":"CPC, arts. 1.009 a 1.014","checkpoints":["cabimento contra sentença","interposição no primeiro grau","questões não agraváveis","efeito suspensivo e exceções","extensão da devolução"]},{"title":"Agravos e embargos","articles":"CPC, arts. 1.015 a 1.026","checkpoints":["cabimento do instrumento","formação e resposta","agravo interno","omissão, contradição, obscuridade e erro material","interrupção do prazo"]},{"title":"Repercussão e repetitivos","articles":"CPC, arts. 1.035 a 1.041; CF, arts. 102, § 3º, e 103-A","checkpoints":["repercussão geral","seleção de representativos","sobrestamento","aplicação da tese","súmula vinculante"]}],"questionGaps":["teoria geral dos recursos","agravo de instrumento e agravo interno","distinção e superação de precedentes","recursos repetitivos fora do recorte de RE e REsp"],"coverageNotice":"Complemente nas plataformas de questões: teoria geral dos recursos; agravo de instrumento e agravo interno; distinção e superação de precedentes; recursos repetitivos fora do recorte de RE e REsp. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m15","ankiDeck":"PROCESSO CIVIL::15 RECURSOS, PRECEDENTES E REPETITIVOS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc16","num":16,"title":"Execução: princípios, títulos, obrigações e Fazenda Pública","subtitle":"CPC, arts. 771 a 823 e 910 a 913","topics":["cpc-m16"],"read":"CPC, arts. 771 a 823 e 910 a 913; CF, art. 100.","read_focus":["Responsabilidade patrimonial e disponibilidade da execução.","Requisitos: obrigação certa, líquida e exigível em título.","Títulos judiciais x extrajudiciais.","Fraude à execução.","Entrega, fazer e não fazer.","Execução contra Fazenda e alimentos."],"outline":["princípios executivos","títulos extrajudiciais","exigibilidade","cumulação","competência","responsabilidade patrimonial","fraude à execução","entrega de coisa","fazer","não fazer","Fazenda Pública","precatórios","RPV","alimentos"],"theory":[["Execução e título","Execução busca satisfação concreta e depende de título com obrigação certa, líquida e exigível. Menor onerosidade não supera efetividade nem transfere ao credor o custo da inércia do devedor."],["Responsabilidade patrimonial","Bens presentes e futuros respondem, ressalvadas impenhorabilidades. Fraude à execução depende das hipóteses legais e produz ineficácia perante o exequente."],["Obrigações específicas","Entrega, fazer e não fazer admitem tutela específica, medidas sub-rogatórias e coercitivas, conversão em perdas e danos e multas."],["Fazenda e alimentos","Fazenda é citada para embargos e paga por precatório/RPV. Execução extrajudicial de alimentos segue regime próprio e dialoga com cumprimento alimentar."],["Espécies executivas","A técnica depende da prestação: entrega usa imissão ou busca e apreensão; fazer pode ser cumprido por terceiro ou convertido; não fazer busca desfazer ou impedir; quantia constrita e expropria; Fazenda segue requisição constitucional. O título e a exigibilidade antecedem a escolha do rito."],["Títulos e responsabilidade","O rol de títulos extrajudiciais é legal, embora normas especiais possam acrescentar documentos. Responsabilidade patrimonial recai sobre bens presentes e futuros, com exceções; fraude à execução torna a alienação ineficaz perante o exequente quando preenchidos os requisitos legais."],["Fazenda Pública","Na execução fundada em título extrajudicial, a Fazenda é citada para embargos em trinta dias. Rejeitada a defesa ou não oposta, expede-se precatório ou RPV conforme valor, natureza e disciplina constitucional."]],"advanced":[["Atipicidade executiva","Medidas atípicas exigem contraditório, proporcionalidade, indícios de ocultação e relação com o resultado útil."],["Título eletrônico","Documentos eletrônicos e assinaturas recebem disciplina atual; verifique requisitos legais e não exija testemunhas quando a lei as dispensa."]],"lawScheme":[{"title":"Parte geral","articles":"CPC, arts. 771 a 796","checkpoints":["aplicação subsidiária","poderes do juiz","partes","competência","requisitos","títulos extrajudiciais","responsabilidade patrimonial"]},{"title":"Disposições gerais","articles":"CPC, arts. 797 a 805","checkpoints":["interesse do exequente","desistência","cumulação","averbação","fraude à execução","menor onerosidade com eficácia"]},{"title":"Entrega, fazer e não fazer","articles":"CPC, arts. 806 a 823","checkpoints":["coisa certa e incerta","imissão e busca","prazo para cumprimento","execução por terceiro","multa e perdas e danos"]},{"title":"Fazenda e alimentos","articles":"CPC, arts. 910 a 913; CF, art. 100","checkpoints":["citação para embargos","precatório","RPV","execução extrajudicial de alimentos"]}],"questionGaps":["espécies de execução em visão comparativa","execução de entrega de coisa","execução de fazer e não fazer","execução contra a Fazenda Pública e regime de RPV"],"coverageNotice":"Complemente nas plataformas de questões: espécies de execução em visão comparativa; execução de entrega de coisa; execução de fazer e não fazer; execução contra a Fazenda Pública e regime de RPV. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m16","ankiDeck":"PROCESSO CIVIL::16 EXECUÇÃO, TÍTULOS, OBRIGAÇÕES E FAZENDA","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc17","num":17,"title":"Execução por quantia, penhora, expropriação e embargos","subtitle":"CPC, arts. 824 a 925","topics":["cpc-m17"],"read":"CPC, arts. 824 a 925.","read_focus":["Citação para pagar em três dias.","Arresto executivo e conversão.","Ordem de penhora e impenhorabilidades.","Dinheiro, faturamento, quotas e salário.","Avaliação e expropriação.","Embargos independem de penhora.","Suspensão e prescrição intercorrente."],"outline":["quantia certa","citação","arresto","penhora","ordem preferencial","impenhorabilidade","substituição","depósito","avaliação","adjudicação","alienação","satisfação","embargos","efeito suspensivo","parcelamento","suspensão","prescrição intercorrente","remição"],"theory":[["Quantia e constrição","Executado é citado para pagar; não localizado, cabe arresto. Penhora individualiza patrimônio e deve respeitar ordem preferencial e bens absolutamente ou relativamente protegidos."],["Impenhorabilidades","Proteções do art. 833 comportam exceções legais. Salário, poupança, instrumentos de trabalho e bem de família devem ser analisados com legislação especial e jurisprudência."],["Expropriação","Adjudicação, alienação por iniciativa particular e leilão convertem bens em satisfação. Avaliação e preferência antecedem destinação do produto."],["Embargos e suspensão","Embargos são ação autônoma e não dependem de penhora, mas efeito suspensivo exige requisitos. Suspensão por ausência de bens inicia regime da prescrição intercorrente."],["Exceção de pré-executividade","É construção jurisprudencial para suscitar, sem embargos e sem garantia do juízo, matéria cognoscível de ofício ou demonstrável de plano, sem dilação probatória incompatível. Não substitui embargos para toda defesa do executado."],["Remição","Até a assinatura do auto de adjudicação ou alienação, o executado pode remir a execução pagando ou consignando a dívida atualizada, juros, custas e honorários. Não confunda remição da execução com institutos materiais ou preferência para adquirir bem."],["Prescrição intercorrente","A ausência de bens pode suspender execução e dar início ao regime temporal do art. 921. O reconhecimento da prescrição intercorrente exige observância dos marcos legais e contraditório; a extinção é formalizada por sentença."]],"advanced":[["Parcelamento do art. 916","Aplica-se à execução de título extrajudicial e implica reconhecimento do crédito e renúncia aos embargos, não sendo regra do cumprimento."],["Menor onerosidade","Devedor deve indicar alternativa mais eficaz e menos gravosa; alegação abstrata não basta para afastar medida útil."]],"lawScheme":[{"title":"Quantia e penhora","articles":"CPC, arts. 824 a 869","checkpoints":["citação em três dias","arresto","ordem e impenhorabilidades","substituição","penhora de dinheiro, créditos, quotas e faturamento"]},{"title":"Avaliação e expropriação","articles":"CPC, arts. 870 a 909","checkpoints":["avaliação","adjudicação","alienação particular","leilão","remição antes da assinatura do ato expropriatório","satisfação"]},{"title":"Embargos","articles":"CPC, arts. 914 a 920","checkpoints":["independência de penhora","prazo","matérias","parcelamento","efeito suspensivo","procedimento"]},{"title":"Suspensão e extinção","articles":"CPC, arts. 921 a 925","checkpoints":["ausência de bens","prescrição intercorrente","suspensão convencionada","extinção por sentença"]}],"questionGaps":["exceção de pré-executividade","remição","suspensão e extinção da execução","prescrição intercorrente"],"coverageNotice":"Complemente nas plataformas de questões: exceção de pré-executividade; remição; suspensão e extinção da execução; prescrição intercorrente. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m17","ankiDeck":"PROCESSO CIVIL::17 PENHORA, EXPROPRIAÇÃO E EMBARGOS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc18","num":18,"title":"Procedimentos especiais previstos no edital","subtitle":"CPC e leis especiais: consignação, embargos de terceiro, monitória e restauração","topics":["cpc-m18"],"read":"CPC, arts. 539 a 549, 674 a 681, 700 a 702 e 712 a 718.","read_focus":["Consignação libera quando depósito é integral e adequado.","Embargos de terceiro protegem posse ou domínio de quem não é parte.","Monitória exige prova escrita sem eficácia executiva.","Restauração recompõe autos desaparecidos.","Não estude todo o livro de procedimentos especiais: siga o recorte do edital."],"outline":["generalidades","consignação em pagamento","depósito insuficiente","embargos de terceiro","legitimidade","prazo","ação monitória","prova escrita","mandado monitório","embargos monitórios","restauração de autos"],"theory":[["Consignação","Devedor deposita coisa ou quantia para liberar-se quando pagamento direto é impossível ou recusado. Depósito insuficiente pode produzir liberação parcial e saldo executável conforme decisão."],["Embargos de terceiro","Quem sofre constrição sobre bem próprio ou que possua, sem integrar o processo, pode pedir desconstituição. Cônjuge, adquirente e atingidos por desconsideração possuem hipóteses legais."],["Monitória","Prova escrita sem força executiva permite mandado de pagar, entregar ou fazer. Cumprido, há benefício; não cumprido e não embargado, forma-se título judicial."],["Restauração","Desaparecidos autos, partes, MP ou juiz podem provocar reconstituição com cópias, certidões e outros elementos, preservando atos comprovados."],["Generalidades dos especiais","Procedimentos especiais adaptam cognição, defesa ou provimento à natureza do direito. O procedimento comum é aplicado subsidiariamente, e técnicas especiais podem ser combinadas quando compatíveis com devido processo e finalidade."],["Consignação em detalhe","A ação busca liberar o devedor mediante prestação integral e adequada quando o pagamento direto falha por causa juridicamente relevante. Contestação pode discutir recusa, local, prazo ou integralidade; depósito insuficiente não equivale automaticamente à quitação total."],["Embargos de terceiro em detalhe","A legitimidade alcança proprietário ou possuidor estranho ao processo e pessoas equiparadas pelo CPC. O prazo varia conforme o tipo de processo e o estágio da alienação; prova sumária pode suspender a constrição ou assegurar manutenção/reintegração provisória."],["Restauração em detalhe","A restauração recompõe autos desaparecidos, não reabre mérito nem apaga atos comprovados. Cópias, certidões, depoimentos e repetição indispensável de prova permitem reconstrução, com responsabilidade de quem causou o desaparecimento."]],"advanced":[["Recorte","Ações possessórias, inventário e família não foram ativados só porque pertencem a procedimentos especiais; o edital enumerou espécies específicas."],["Monitória contra Fazenda","É admitida, com adaptações do regime público e formação do título nos termos do CPC."]],"lawScheme":[{"title":"Consignação","articles":"CPC, arts. 539 a 549","checkpoints":["hipóteses materiais de depósito","depósito bancário","prestações sucessivas","respostas do réu","insuficiência e efeitos"]},{"title":"Embargos de terceiro","articles":"CPC, arts. 674 a 681","checkpoints":["posse ou domínio incompatível com constrição","legitimados equiparados","prazo","competência","liminar e honorários"]},{"title":"Monitória","articles":"CPC, arts. 700 a 702","checkpoints":["prova escrita sem eficácia executiva","conteúdo do mandado","benefício pelo cumprimento","embargos","Fazenda Pública"]},{"title":"Restauração","articles":"CPC, arts. 712 a 718","checkpoints":["legitimidade","documentos e certidões","responsabilidade pelo desaparecimento","reprodução de provas","prosseguimento dos autos"]}],"questionGaps":["embargos de terceiro","restauração de autos","características gerais dos procedimentos especiais","consignação além das hipóteses presentes no banco"],"coverageNotice":"Complemente nas plataformas de questões: embargos de terceiro; restauração de autos; características gerais dos procedimentos especiais; consignação além das hipóteses presentes no banco. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m18","ankiDeck":"PROCESSO CIVIL::18 PROCEDIMENTOS ESPECIAIS PREVISTOS","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc19","num":19,"title":"Ações coletivas, constitucionais e controle de constitucionalidade","subtitle":"Leis 4.717/1965, 7.347/1985, 12.016/2009, 13.300/2016 e 9.507/1997","topics":["cpc-m19"],"read":"Lei da Ação Popular; Lei da Ação Civil Pública; Lei do Mandado de Segurança; Lei do Mandado de Injunção; Lei do Habeas Data; CF e Leis 9.868/1999 e 9.882/1999.","read_focus":["Identifique legitimidade, objeto, competência, prazo e coisa julgada de cada ação.","Ação Popular é do cidadão; ACP possui rol próprio.","MS exige direito líquido e certo e prazo decadencial.","MI combate falta de norma regulamentadora.","Habeas data protege dados pessoais.","Compare controle concentrado e incidental."],"outline":["ação popular","ação civil pública","mandado de segurança","mandado de segurança coletivo","mandado de injunção","habeas data","ADI","ADC","ADPF","controle incidental","legitimidade","competência","liminar","coisa julgada coletiva"],"theory":[["Ações coletivas","Ação Popular protege patrimônio público, moralidade, ambiente e patrimônio cultural por iniciativa cidadã. ACP tutela interesses difusos, coletivos e individuais homogêneos por legitimados legais."],["Mandado de segurança","Protege direito líquido e certo não amparado por HC ou HD contra ilegalidade ou abuso de autoridade; prova deve ser pré-constituída e decadência é de 120 dias."],["MI e habeas data","MI enfrenta omissão que inviabiliza direito constitucional; habeas data assegura conhecimento, retificação ou anotação de dados pessoais em registros públicos ou de caráter público."],["Controle de constitucionalidade","ADI e ADC seguem processo objetivo perante o STF; controle incidental surge em caso concreto e deve observar reserva de plenário e efeitos próprios."],["Ação Popular","Somente cidadão em gozo dos direitos políticos possui legitimidade ativa; a demanda combate ato lesivo ao patrimônio público, moralidade, ambiente ou patrimônio histórico-cultural. O Ministério Público acompanha, pode assumir em hipóteses legais e promove execução se o autor não o fizer."],["Ação Civil Pública","Legitimados atuam de forma concorrente e disjuntiva na tutela de interesses transindividuais. Inquérito civil é instrumento do Ministério Público, mas não condição geral da ação. Obrigações de fazer, não fazer e reparar podem ser combinadas conforme o dano."],["Mandado de segurança","A prova deve existir previamente, pois o rito não comporta dilação probatória comum. O prazo decadencial é de 120 dias da ciência do ato impugnado. O coletivo altera legitimidade, não elimina os requisitos materiais do remédio."],["Mandado de injunção","Cabe quando ausência total ou parcial de norma regulamentadora inviabiliza direito, liberdade ou prerrogativa constitucional. A decisão pode fixar condições para exercício e tem regime de eficácia individual ou coletiva previsto em lei."],["Habeas data","Protege acesso, retificação ou anotação de dados pessoais em registro público ou de caráter público. A resistência administrativa deve estar demonstrada nas formas legais; o remédio não serve para obter toda e qualquer informação estatal."],["ADI, ADC e controle incidental","ADI e ADC são processos objetivos de competência do STF, com legitimados constitucionais, efeitos gerais e vinculantes nas condições legais. No controle incidental, a questão constitucional surge como fundamento de caso concreto e, no tribunal, observa a reserva de plenário e o incidente dos arts. 948 a 950 do CPC."]],"advanced":[["Coisa julgada coletiva","Extensão varia conforme direito tutelado, resultado e competência territorial à luz da legislação e jurisprudência; evite fórmula única."],["Fungibilidade","Ações constitucionais têm pressupostos próprios; erro de via não é automaticamente corrigido quando faltar condição específica."]],"lawScheme":[{"title":"Ações coletiva e popular","articles":"Lei 4.717/1965, arts. 1º, 5º a 7º, 9º, 11 a 13 e 18 a 20; Lei 7.347/1985, arts. 1º a 5º, 11 a 13 e 16 a 21","checkpoints":["legitimidade","objeto","competência","liminar","coisa julgada e execução"]},{"title":"Mandado de segurança","articles":"Lei 12.016/2009, arts. 1º a 7º e 21 a 25; CF, art. 5º, LXIX e LXX","checkpoints":["direito líquido e certo","autoridade coatora","prova pré-constituída","liminar","prazo de 120 dias","legitimação coletiva"]},{"title":"Injunção e habeas data","articles":"Lei 13.300/2016, arts. 1º a 13; Lei 9.507/1997, arts. 7º a 21; CF, art. 5º, LXXI e LXXII","checkpoints":["omissão regulamentadora","efeitos da decisão","dados pessoais","pretensão administrativa prévia","gratuidade constitucional"]},{"title":"Controle de constitucionalidade","articles":"CF, arts. 97, 102, I, a, e 103; Lei 9.868/1999, arts. 2º a 4º, 10 a 12 e 21 a 28","checkpoints":["reserva de plenário","legitimados","cautelar","efeitos da decisão","modulação; o incidente dos arts. 948 a 950 é revisado no Módulo 20"]}],"questionGaps":["ação popular","mandado de segurança individual e coletivo","mandado de injunção","habeas data","ADI e ADC","declaração incidental de inconstitucionalidade"],"coverageNotice":"Complemente nas plataformas de questões: ação popular; mandado de segurança individual e coletivo; mandado de injunção; habeas data; ADI e ADC; declaração incidental de inconstitucionalidade. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m19","ankiDeck":"PROCESSO CIVIL::19 AÇÕES COLETIVAS, CONSTITUCIONAIS E CONTROLE","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"},{"id":"cpc20","num":20,"title":"Processos nos tribunais, rescisória, IAC, IRDR e reclamação","subtitle":"CPC, arts. 947, 948 a 993","topics":["cpc-m20"],"read":"CPC, arts. 947, 948 a 993; CF, arts. 102 e 105.","read_focus":["IAC x IRDR: pressupostos e efeitos.","Arguição de inconstitucionalidade e reserva de plenário.","Conflito de competência.","Ação rescisória: hipóteses, legitimidade, prazo e depósito.","Reclamação: finalidades e subsidiariedade.","Competência originária dos tribunais."],"outline":["ordem nos tribunais","IAC","arguição de inconstitucionalidade","conflito de competência","homologação estrangeira","ação rescisória","hipóteses","prazo decadencial","juízo rescindente e rescisório","IRDR","reclamação","precedentes qualificados"],"theory":[["Incidentes e uniformização","IAC resolve relevante questão com repercussão social sem multiplicidade repetitiva; IRDR exige repetição efetiva e risco à isonomia e segurança. Ambos formam precedentes qualificados."],["Arguição e conflito","Órgão fracionário submete questão constitucional ao plenário ou órgão especial quando cabível. Conflito resolve disputa entre juízos sobre competência ou reunião."],["Ação rescisória","Desconstitui decisão de mérito transitada nas hipóteses taxativas, dentro do prazo decadencial. Pode exigir depósito e possui juízo rescindente e, quando cabível, rescisório."],["Reclamação","Preserva competência e autoridade de decisões, súmulas vinculantes e precedentes qualificados nas hipóteses legais; não substitui recurso comum nem ação rescisória."],["IAC x IRDR","IAC pressupõe questão relevante, grande repercussão social e ausência de repetição em múltiplos processos, podendo também prevenir ou compor divergência interna. IRDR exige repetição efetiva e risco à isonomia e segurança. Ambos geram precedente qualificado, mas possuem gatilhos diferentes."],["Arguição de inconstitucionalidade","Órgão fracionário não declara inconstitucionalidade quando a questão deve ser submetida ao plenário ou órgão especial, ressalvadas hipóteses legais de decisão anterior. O incidente resolve a questão constitucional e o processo retorna para aplicação ao caso."],["Rescisória e reclamação","A rescisória desconstitui decisão transitada por vício taxativo dentro do prazo decadencial; reclamação preserva competência, autoridade e observância de decisões ou precedentes nas hipóteses legais. Nenhuma delas funciona como recurso tardio genérico."]],"advanced":[["Querela nullitatis","Vício transrescisório, como falta de citação em processo revel, pode ser arguido sem submeter-se automaticamente ao prazo da rescisória."],["IRDR e recursos","Tese deve ser aplicada aos processos abrangidos; recursos aos tribunais superiores podem produzir efeitos nacionais conforme o CPC."]],"lawScheme":[{"title":"IAC e arguição","articles":"CPC, arts. 947 a 950","checkpoints":["relevante questão sem repetição múltipla","prevenção ou composição de divergência","reserva de plenário","manifestação do Ministério Público e pessoas jurídicas responsáveis"]},{"title":"Conflito","articles":"CPC, arts. 951 a 959","checkpoints":["conflito positivo e negativo","legitimidade para suscitar","relator e suspensão","decisão e designação do juízo"]},{"title":"Ação rescisória","articles":"CPC, arts. 966 a 975","checkpoints":["decisões rescindíveis","hipóteses taxativas","legitimidade","depósito","tutela provisória","prazo decadencial"]},{"title":"IRDR e reclamação","articles":"CPC, arts. 976 a 993","checkpoints":["repetição e risco à isonomia","admissão e suspensão","tese e abrangência","preservação de competência e autoridade","subsidiariedade e esgotamento"]}],"questionGaps":["incidente de assunção de competência","arguição de inconstitucionalidade","conflito de competência em procedimento próprio"],"coverageNotice":"Complemente nas plataformas de questões: incidente de assunção de competência; arguição de inconstitucionalidade; conflito de competência em procedimento próprio. A teoria e a leitura esquematizada deste módulo cobrem esses pontos.","editalModule":"cpc-m20","ankiDeck":"PROCESSO CIVIL::20 TRIBUNAIS, RESCISÓRIA, IAC, IRDR E RECLAMAÇÃO","auditStatus":"disciplina-e-anki-alinhados-edital-cargo-16-v6636"}];

